def _read_json_dict_required_12c2(path: str, label: str) -> dict:
    if not os.path.exists(path):
        raise RuntimeError(f"[Cell12.c.2] Missing required {label}: {path}")
    with open(path, "r", encoding="utf-8") as f:
        obj = json.load(f)
    if not isinstance(obj, dict):
        raise RuntimeError(f"[Cell12.c.2] Required {label} must be a JSON object: {path}")
    return obj

