def _cell12c2_hash_obj(obj: Any) -> str:
    payload = json.dumps(obj, sort_keys=True, default=str, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


def _cell12c2_numeric_hash_12c2(values: Any) -> str:
    arr = np.asarray(values)
    return hashlib.sha256(np.ascontiguousarray(arr).view(np.uint8)).hexdigest()


def _cell12c2_cfg_hash_12c2() -> str:
    relevant = {
        str(k): v for k, v in CFG.items()
        if str(k).startswith("cell12c2_")
        and str(k) not in {
            "cell12c2_mode",
            "cell12c2_column_filter",
            "cell12c2_generator_filter",
            "cell12c2_family_filter",
            "cell12c2_use_candidate_cache",
            "cell12c2_force_recompute",
            "cell12c2_cache_dir",
        }
    }
    return _cell12c2_hash_obj(relevant)


def _cell12c2_performance_timing_df_12c2() -> pd.DataFrame:
    rows = [{"stage": k, "seconds": float(v)} for k, v in CELL12C2_STAGE_TIMING.items()]
    for fam, sec in sorted(CELL12C2_MATERIALIZATION_SECONDS_BY_FAMILY.items()):
        rows.append({"stage": f"materialization_seconds_by_generator_family::{fam}", "seconds": float(sec)})
    for gen, sec in sorted(CELL12C2_GENERATOR_SECONDS.items(), key=lambda kv: kv[1], reverse=True)[:20]:
        rows.append({"stage": f"slowest_generator::{gen}", "seconds": float(sec)})
    return pd.DataFrame(rows)


def _cell12c2_write_performance_timing_12c2(path: Optional[str] = None) -> str:
    CELL12C2_STAGE_TIMING["total_seconds"] = float(time.perf_counter() - CELL12C2_PERF_START)
    timing_path = path or os.path.join(REPORT_DIR, "cell12c2_performance_timing_audit.csv")
    _cell12c2_performance_timing_df_12c2().to_csv(timing_path, index=False)
    return timing_path


def _cell12c2_stop_cleanly_12c2(message: str) -> None:
    log(message)
    raise SystemExit(message)


def _cell12c2_candidate_group_12c2(gen: str) -> str:
    if gen in SPECIALIZED_GENERATORS:
        return "specialized_train_only"
    if gen in STATISTICAL_GENERATORS:
        return "statistical_train_only"
    if gen in SEQUENCE_GENERATORS:
        return "sequence_train_only"
    return "unknown"


def _cell12c2_materializer_name_12c2(gen: str) -> str:
    return f"_generate_candidate::{str(gen)}"


def _cell12c2_cache_fingerprint_12c2(col: str, gen: str, candidate_id: str) -> Dict[str, Any]:
    fit = TRAIN_FIT[str(col)]
    fp = {
        "candidate_id": str(candidate_id),
        "source_col": str(col),
        "generator": str(gen),
        "cell12c2_version": CELL12C2_VERSION,
        "cell12c2_gate_version": CELL12C2_GATE_VERSION,
        "generator_family_version": _generator_family_version_12c2(str(gen)),
        "relevant_cfg_hash": _cell12c2_cfg_hash_12c2(),
        "train_observed_values_hash": _cell12c2_numeric_hash_12c2(getattr(fit, "train_obs", np.array([], dtype=np.float32))),
        "val_observed_mask_hash": _cell12c2_numeric_hash_12c2(np.asarray(getattr(fit, "val_mask", np.array([], dtype=bool)), dtype=np.uint8)),
        "semantic_route_policy_hash": _cell12c2_hash_obj(
            {
                "policy": "cell12c2_semantic_route_policy_v4_power_current_counter_applicability",
                "semantic_veto": _cell12c2_semantic_route_veto(str(col), str(gen)),
            }
        ),
        "candidate_materializer_function_name": _cell12c2_materializer_name_12c2(str(gen)),
        "candidate_materializer_function_version": CELL12C2_VERSION,
    }
    fp["fingerprint_hash"] = _cell12c2_hash_obj(fp)
    return fp


def _cell12c2_cache_paths_12c2(fingerprint_hash: str) -> Dict[str, str]:
    shard = str(fingerprint_hash)[:2]
    cache_subdir = os.path.join(CELL12C2_CACHE_DIR, shard)
    os.makedirs(cache_subdir, exist_ok=True)
    stem = os.path.join(cache_subdir, str(fingerprint_hash))
    return {
        "vector": f"{stem}.npy",
        "row": f"{stem}.row.pkl",
        "fingerprint": f"{stem}.fingerprint.json",
    }


CELL12C2_CACHE_READ_MODES = {"full"}
