def _cell12c2_try_load_candidate_cache_12c2(fingerprint):
    # Reuse is forbidden. Every candidate is fitted/materialized in this run.
    return None


def _cell12c2_save_candidate_cache_12c2(
    fingerprint: Optional[Dict[str, Any]],
    y: np.ndarray,
    row_out: Dict[str, Any],
) -> None:
    if (
        not fingerprint
        or not CELL12C2_USE_CANDIDATE_CACHE
        or CELL12C2_MODE not in CELL12C2_CACHE_WRITE_MODES
    ):
        return
    try:
        paths_12c2 = _cell12c2_cache_paths_12c2(str(fingerprint.get("fingerprint_hash", "")))
        np.save(paths_12c2["vector"], np.asarray(y, dtype=np.float32), allow_pickle=False)
        with open(paths_12c2["row"], "wb") as f:
            pickle.dump(dict(row_out), f, protocol=pickle.HIGHEST_PROTOCOL)
        with open(paths_12c2["fingerprint"], "w", encoding="utf-8") as f:
            json.dump(fingerprint, f, indent=2, sort_keys=True)
    except Exception as exc:
        log(f"[Cell12.c.2][WARN] Candidate cache save ignored | hash={fingerprint.get('fingerprint_hash', '')} | reason={exc}")

