# ----------------------------------------------------------
# 1. Generic helpers
# ----------------------------------------------------------
def _rng_for(*parts: Any) -> np.random.Generator:
    payload = "::".join([str(SEED)] + [str(p) for p in parts])
    h = hashlib.sha256(payload.encode("utf-8")).digest()
    return np.random.default_rng(int.from_bytes(h[:8], "little", signed=False))


def _safe_log(msg: str) -> None:
    try:
        log(msg)
    except Exception:
        print(msg)


def _ensure_numeric_series(frame: pd.DataFrame, col: str, n_expected: int) -> pd.Series:
    if col not in frame.columns:
        return pd.Series(np.full(n_expected, np.nan, dtype=np.float32), index=frame.index)
    return pd.to_numeric(frame[col], errors="coerce")


def _finite_np(x: Any) -> np.ndarray:
    arr = np.asarray(x, dtype=np.float64)
    return arr[np.isfinite(arr)]


def _nan_array(n: int) -> np.ndarray:
    return np.full(int(n), np.nan, dtype=np.float32)


def _round_support(x: np.ndarray, decimals: int = 6) -> np.ndarray:
    y = _finite_np(x)
    if y.size == 0:
        return np.array([], dtype=np.float64)
    return np.round(y.astype(np.float64), int(decimals))


def _infer_entity(col: str) -> str:
    s = str(col)
    if s.startswith("iot__"):
        rest = s[len("iot__"):]
        marker_positions = []
        for marker in ["__sensor__", "__binary_sensor__", "__switch__", "__light__", "__number__", "__select__"]:
            p = rest.find(marker)
            if p >= 0:
                marker_positions.append(p)
        if marker_positions:
            return rest[:min(marker_positions)]
        parts = rest.split("__")
        return parts[0] if parts else rest
    return s.split("__")[0]


def _family_for_col(col: str) -> str:
    if isinstance(FAMILY_MAP, dict):
        return str(FAMILY_MAP.get(col, "unknown"))
    try:
        return str(FAMILY_MAP.loc[col])
    except Exception:
        return "unknown"


def _subfamily_for_col(col: str) -> str:
    if isinstance(SYNTHESIS_SUBFAMILY_MAP, dict):
        return str(SYNTHESIS_SUBFAMILY_MAP.get(col, "unknown"))
    try:
        return str(SYNTHESIS_SUBFAMILY_MAP.loc[col])
    except Exception:
        return "unknown"


def _raw_field_name_12c2(col: str) -> str:
    s = str(col)
    if "__sensor__" in s:
        tail = s.split("__sensor__", 1)[1]
    elif "__state__" in s:
        tail = s.rsplit("__", 2)[0]
    else:
        tail = s.split("__")[-2] if s.endswith("__value") and "__" in s else s.split("__")[-1]
    return tail.replace("__value", "").replace("__state", "")


def _entity_derived_state_measurement_12c2(col: str) -> str:
    ent = _infer_entity(col).lower()
    ent = re.sub(r"_pid_[0-9a-z]+$", "", ent)
    for prefix in ("s5_max_", "withings_"):
        if ent.startswith(prefix):
            ent = ent[len(prefix):]
    return ent.strip("_")


def _measurement_field_name_12c2(col: str) -> str:
    s = str(col)
    for marker in ["__sensor__", "__binary_sensor__", "__switch__", "__light__", "__number__", "__select__"]:
        if marker in s:
            tail = s.split(marker, 1)[1]
            raw_parts = [p for p in tail.split("__") if p]
            parts = [p for p in raw_parts if p not in {"value", "state"}]
            if parts:
                return "__".join(parts)
            if raw_parts and all(p in {"state", "value"} for p in raw_parts):
                derived = _entity_derived_state_measurement_12c2(col)
                if derived:
                    return derived
            return _raw_field_name_12c2(col)
    return _raw_field_name_12c2(col)


def _field_name(col: str) -> str:
    return _measurement_field_name_12c2(col)


