def _is_linkquality(col: str) -> bool:
    s = str(col).lower()
    return any(tok in s for tok in ["linkquality", "lqi", "rssi", "signal_strength", "signal_level", "strength"])


def _is_link_signal_telemetry_col_12c2(col: str, fit_override: Optional["TrainFit"] = None) -> bool:
    field = _norm_txt_12c2(_measurement_field_name_12c2(col))
    s = str(col).lower()
    link_tokens = {
        "linkquality", "link_quality", "lqi", "rssi",
        "signal_strength", "signal_level", "signal", "strength",
    }
    explicit_field = bool(field in link_tokens or any(tok in field for tok in link_tokens))
    explicit_col = bool(any(tok in s for tok in [
        "__sensor__linkquality__value", "__sensor__signal_strength__value",
        "__sensor__signal_level__value", "__sensor__rssi__value",
    ]))
    if not (explicit_field or explicit_col):
        return False
    excluded_field = any(tok in field for tok in [
        "temperature", "device_temperature", "voltage", "battery", "humidity",
        "pressure", "consumption", "energy", "current", "power", "count",
        "total", "time", "duration", "gust", "wind", "anemometer",
    ])
    excluded_col = any(tok in s for tok in [
        "temperature", "voltage", "battery", "humidity", "pressure", "consumption",
        "energy", "current", "power", "withings", "__s5_", "s5_max", "x_axis",
        "y_axis", "z_axis", "gust", "wind", "anemometer",
    ])
    if excluded_field and not any(tok in field for tok in link_tokens):
        return False
    if excluded_col and not any(tok in s for tok in ["linkquality", "link_quality", "signal_strength", "signal_level", "rssi"]):
        return False
    fit = fit_override if fit_override is not None else (TRAIN_FIT.get(col) if isinstance(globals().get("TRAIN_FIT", None), dict) else None)
    if fit is not None:
        if getattr(fit, "obs_n", 0) < MIN_TRAIN_OBS:
            return False
        if not (getattr(fit, "is_low_card", False) or getattr(fit, "support_n", 10**9) <= LOWCARD_MAX_UNIQUE):
            return False
    return True


def _is_voltage_battery_temp(col: str) -> bool:
    s = str(col).lower()
    return any(tok in s for tok in ["voltage", "battery", "battery_level", "device_temperature"])


def _is_pressure(col: str) -> bool:
    s = str(col).lower()
    return "pressure" in s or _family_for_col(col).lower() == "pressure"


def _is_humidity(col: str) -> bool:
    s = str(col).lower()
    return "humidity" in s or _family_for_col(col).lower() == "humidity"


def _is_environmental(col: str) -> bool:
    s = str(col).lower()
    fam = _family_for_col(col).lower()
    return fam in {"temperature", "humidity", "pressure", "environmental"} or any(
        tok in s for tok in ["temperature", "humidity", "pressure", "illuminance", "light_level"]
    )


def _is_temperature_environmental_candidate_col_12c2(col: str, fit_override: Optional["TrainFit"] = None) -> bool:
    s = str(col).lower()
    field = _measurement_field_name_12c2(col).lower().replace("-", "_")
    if field not in {"temperature", "ambient_temperature"} and "temperature" not in field:
        return False
    if any(tok in field for tok in ["device_temperature", "device_temp"]):
        return False
    if any(tok in s for tok in [
        "device_temperature", "device_temp", "voltage", "battery", "linkquality", "link_quality",
        "rssi", "signal", "humidity", "pressure", "withings", "s5", "power", "current",
        "consumption", "energy", "count", "total", "x_axis", "y_axis", "z_axis",
    ]):
        return False
    if _is_s5(col) or _is_withings(col) or _is_counter_like(col) or _is_cumulative_power_consumption_col(col):
        return False
    fit = fit_override if fit_override is not None else TRAIN_FIT.get(col)
    if fit is None:
        return False
    if bool(getattr(fit, "is_sparse", False)):
        return False
    if int(getattr(fit, "obs_n", 0)) < max(int(MIN_TRAIN_OBS), 24):
        return False
    return True


def _is_counter_like(col: str) -> bool:
    s = str(col).lower()
    return any(tok in s for tok in [
        "count", "total", "consumption", "energy", "coffees",
        "events_total", "event_count", "events_entity_unique",
        "entity_unique", "trigger_count", "cleaning_count",
    ])


def _is_power_device_col(col: str) -> bool:
    s = str(col).lower()
    return any(tok in s for tok in ["plug", "kasa", "smart_plug"])


def _is_ps5_smart_plug_entity_12c2(col: str) -> bool:
    entity = _infer_entity(col).lower().replace("-", "_")
    return bool("smart_plug_ps5" in entity or "ps5_current" in entity)


def _is_explicit_cumulative_power_bucket_12c2(col: str) -> bool:
    s = str(col).lower()
    entity = _infer_entity(col).lower().replace("-", "_")
    field = _measurement_field_name_12c2(col).lower().replace("-", "_")
    cumulative_fields = {
        "total_consumption",
        "today_s_consumption",
        "today_consumption",
        "this_month_s_consumption",
        "this_month_consumption",
        "monthly_consumption",
        "daily_consumption",
        "energy_total",
        "total_energy",
    }
    entity_bucket_tokens = {
        "today_s",
        "today",
        "this_month_s",
        "this_month",
        "month_s",
        "monthly",
        "daily",
        "total",
        "energy_total",
        "total_energy",
    }
    full_string_bucket_tokens = {
        "total_consumption",
        "today_s",
        "today_s_consumption",
        "today_consumption",
        "this_month_s",
        "this_month_s_consumption",
        "this_month_consumption",
        "month_s",
        "monthly_consumption",
        "daily_consumption",
        "energy_total",
        "total_energy",
    }
    if field in cumulative_fields:
        return True
    if field == "consumption" and any(tok in entity for tok in entity_bucket_tokens):
        return True
    return bool(any(tok in s for tok in full_string_bucket_tokens))


def _is_instantaneous_or_episode_power_col_12c2(col: str) -> bool:
    """
    Instantaneous or near-instantaneous power telemetry.
    Do not include cumulative/monthly/total consumption here.
    """
    s = str(col).lower()
    field = _measurement_field_name_12c2(col).lower().replace("-", "_")
    entity = _infer_entity(col).lower().replace("-", "_")
    if not _is_power_device_col(col):
        return False
    if _is_explicit_cumulative_power_bucket_12c2(col):
        return False
    if field in {"current", "power", "current_consumption"}:
        return True
    if any(tok in s for tok in [
        "__sensor__current__value",
        "current_consumption",
        "__sensor__power__value",
    ]):
        return True
    if field == "consumption" and (
        "smart_plug_ps5_current" in entity
        or any(tok in entity for tok in ["current", "episode", "instantaneous"])
    ):
        return True
    return False


def _is_instantaneous_power_current_col(col: str) -> bool:
    return _is_instantaneous_or_episode_power_col_12c2(col)


def _is_cumulative_power_consumption_col(col: str) -> bool:
    """
    Cumulative or bucketed energy/consumption telemetry.
    These need reset/cycle/plateau support modeling, not current episode replay.
    """
    if not _is_power_device_col(col):
        return False
    if _is_instantaneous_or_episode_power_col_12c2(col):
        return False
    return bool(_is_explicit_cumulative_power_bucket_12c2(col))


def _is_power_current(col: str) -> bool:
    # Backward-compatible name. Keep it narrow now.
    return _is_instantaneous_power_current_col(col)

def _is_s5(col: str) -> bool:
    """
    True only for Roborock/S5 vacuum entities.

    Important:
    - Must not match PS5 smart plug entities such as
      iot__smart_plug_ps5_current__sensor__consumption__value.
    - Use entity and family metadata, not raw full-column substring matching.
    """
    entity = _infer_entity(col).lower().replace("-", "_")
    fam = _family_for_col(col).lower().replace("-", "_")

    if fam == "s5":
        return True

    return bool(
        entity == "s5"
        or entity.startswith("s5_")
        or entity.startswith("s5_max_")
    )


