def _postprocess(col: str, y: Any, fit: Optional["TrainFit"] = None) -> np.ndarray:
    arr = np.asarray(y, dtype=np.float32).copy()
    if arr.ndim != 1:
        arr = arr.reshape(-1).astype(np.float32)
    if _domain_nonnegative(col):
        arr[np.isfinite(arr)] = np.maximum(arr[np.isfinite(arr)], 0.0)
    if fit is not None and fit.obs_n > 0:
        # Keep continuous candidates inside TRAIN robust bounds, not TEST/VAL bounds.
        lo, hi = fit.clip_lo, fit.clip_hi
        if np.isfinite(lo) and np.isfinite(hi) and hi >= lo:
            arr[np.isfinite(arr)] = np.clip(arr[np.isfinite(arr)], lo, hi)
        if _should_project_to_train_support_12c2(col, fit):
            arr = _project_to_support(arr, fit.support)
    return arr.astype(np.float32)


def _project_to_support(y: Any, support: np.ndarray) -> np.ndarray:
    arr = np.asarray(y, dtype=np.float32).copy()
    sup = np.asarray(support, dtype=np.float32)
    if sup.size == 0:
        return arr
    finite = np.isfinite(arr)
    if not finite.any():
        return arr
    # Efficient enough for low-card signals.
    vals = arr[finite].astype(np.float32)
    idx = np.abs(vals[:, None] - sup[None, :]).argmin(axis=1)
    arr[finite] = sup[idx]
    return arr.astype(np.float32)

def _json_safe_12c2(obj: Any) -> Any:
    if isinstance(obj, dict):
        return {str(k): _json_safe_12c2(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple, set)):
        return [_json_safe_12c2(v) for v in obj]
    if isinstance(obj, (np.integer,)):
        return int(obj)
    if isinstance(obj, (np.floating, float)):
        x = float(obj)
        return None if not np.isfinite(x) else x
    if isinstance(obj, (np.bool_,)):
        return bool(obj)
    return obj

def _compress_reasons(reasons: Iterable[str]) -> str:
    toks = []
    seen = set()
    for r in reasons:
        if r is None:
            continue
        for t in str(r).replace("|", ",").split(","):
            t = t.strip()
            if t and t not in seen:
                toks.append(t); seen.add(t)
    return "|".join(toks)


def _candidate_variant_key_12c2(col: str, gen: str, eligible_source: str = "") -> str:
    """
    Stable candidate variant key.

    This must not depend on row order. Cell 12.c.3 joins publication metadata
    back to canonical metrics by candidate_id, so the ID must be deterministic
    from candidate identity, not from the materialization loop index.
    """
    fit = TRAIN_FIT.get(str(col))
    parts = [
        str(col),
        str(gen),
        str(eligible_source or ""),
        str(fit.family if fit is not None else ""),
        str(fit.subfamily if fit is not None else ""),
        str(fit.field if fit is not None else ""),
    ]
    return "|".join(parts)


def _candidate_id(col: str, gen: str, eligible_source: str = "") -> str:
    payload = _candidate_variant_key_12c2(col, gen, eligible_source)
    h = hashlib.sha1(f"{CELL12C2_VERSION}|{payload}".encode("utf-8")).hexdigest()[:16]
    stem = re.sub(r"[^A-Za-z0-9]+", "_", str(gen)).strip("_")[:56]
    return f"cand__{stem}__{h}"
