def _is_counter_progression_publication_guard_col_12c2(col: str) -> bool:
    """
    Return True for cumulative/count/progression-style numeric measurements
    where monotonic/reset/increment plausibility is a publication-safety issue.

    The parsed measurement field is authoritative. Entity names can contain
    misleading terms such as "current", but if the parsed field is
    "consumption", "energy", "coffees", "cups", or a count field, it should
    still be guarded.
    """
    col_l = str(col).lower().replace("-", "_")
    field_l = _measurement_field_name_12c2(col).lower().replace("-", "_")
    family_l = _family_for_col(col).lower().replace("-", "_")
    subfamily_l = _subfamily_for_col(col).lower().replace("-", "_")

    # S5: only true count measurements are progression-guarded.
    if _is_s5(col):
        return bool(
            field_l in {"total_cleaning_count", "cleaning_count"}
            or field_l.endswith("_cleaning_count")
        )

    # Withings metrics are session summaries, not monotonic counters.
    if _is_withings(col):
        return False

    if _is_instantaneous_or_episode_power_col_12c2(col):
        return False

    # Strong field-level positive cases.
    # These must come after episode-power checks so PS5 current consumption is
    # not treated as a cumulative publication counter.
    cumulative_or_count_fields = {
        "total_consumption",
        "today_s_consumption",
        "this_month_s_consumption",
        "energy",
        "energy_total",
        "total_energy",
        "coffees",
        "cups",
        "coffee_and_milk_cups",
        "hot_water_cups",
        "trigger_count",
        "event_count",
        "events_entity_unique",
        "entity_unique",
        "events_total",
        "total_count",
        "total_cleaning_count",
    }
    if field_l in cumulative_or_count_fields:
        return True
    if field_l == "consumption":
        return bool(_is_cumulative_power_consumption_col(col))

    if field_l.endswith("_count") and not any(tok in field_l for tok in ["discount", "account"]):
        return True

    # Strong field-level negative cases: instantaneous or quasi-static telemetry.
    instantaneous_or_state_fields = {
        "current",
        "power",
        "voltage",
        "pressure",
        "humidity",
        "temperature",
        "device_temperature",
        "battery",
        "battery_level",
        "linkquality",
        "lqi",
        "rssi",
        "signal",
        "signal_strength",
        "signal_level",
        "strength",
        "x_axis",
        "y_axis",
        "z_axis",
        "cleaning_time",
        "cleaning_area",
        "total_cleaning_time",
        "total_cleaning_area",
        "time_left",
        "filter_time_left",
        "main_brush_time_left",
        "side_brush_time_left",
        "sensor_time_left",
    }
    if field_l in instantaneous_or_state_fields:
        return False

    if any(tok in field_l for tok in [
        "voltage",
        "pressure",
        "humidity",
        "temperature",
        "linkquality",
        "rssi",
        "signal",
        "current",
        "power",
        "time_left",
        "cleaning_time",
        "cleaning_area",
    ]):
        return False

    # Metadata fallback for explicitly counter-like families/subfamilies.
    meta_l = f"{family_l} {subfamily_l}"
    if any(tok in meta_l for tok in ["cumulative_count", "counter", "accumulator"]):
        return True

    # Conservative final fallback: count-like column names only.
    if any(tok in col_l for tok in [
        "trigger_count",
        "event_count",
        "events_entity_unique",
        "entity_unique",
        "events_total",
        "total_count",
        "counter",
    ]):
        return True

    return False


