# ----------------------------------------------------------
# 2. Fit cache
# ----------------------------------------------------------
@dataclass
class TrainFit:
    col: str
    entity: str
    family: str
    subfamily: str
    field: str
    train_full: np.ndarray
    train_obs: np.ndarray
    val_mask: np.ndarray
    obs_n: int
    obs_rate: float
    median: float
    mean: float
    std: float
    q001: float
    q005: float
    q01: float
    q05: float
    q10: float
    q50: float
    q90: float
    q95: float
    q99: float
    q995: float
    q999: float
    clip_lo: float
    clip_hi: float
    support: np.ndarray
    support_probs: np.ndarray
    support_n: int
    is_low_card: bool
    is_sparse: bool
    positive_rate: float
    transitions: Dict[float, np.ndarray]
    transition_probs: Dict[float, np.ndarray]
    run_values: np.ndarray
    run_lengths: np.ndarray


def _fit_column(col: str) -> TrainFit:
    x_full = _ensure_numeric_series(df_tr, col, N_TR).to_numpy(dtype=np.float32, copy=True)
    val_x = _ensure_numeric_series(df_val, col, N_VAL).to_numpy(dtype=np.float32, copy=True)
    val_mask = np.isfinite(val_x)
    obs = np.isfinite(x_full)
    x_obs = x_full[obs].astype(np.float32, copy=False)
    obs_n = int(x_obs.size)
    obs_rate = float(obs_n) / max(float(N_TR), 1.0)

    if obs_n == 0:
        q = {k: 0.0 for k in ["q001","q005","q01","q05","q10","q50","q90","q95","q99","q995","q999"]}
        support = np.array([0.0], dtype=np.float32)
        support_probs = np.array([1.0], dtype=np.float64)
        median = mean = 0.0
        std = 0.0
    else:
        probs = [0.001, 0.005, 0.01, 0.05, 0.10, 0.50, 0.90, 0.95, 0.99, 0.995, 0.999]
        qvals = np.quantile(x_obs.astype(np.float64), probs)
        q = dict(zip(["q001","q005","q01","q05","q10","q50","q90","q95","q99","q995","q999"], [float(v) for v in qvals]))
        rounded = np.round(x_obs.astype(np.float64), 6)
        uniq, cnt = np.unique(rounded, return_counts=True)
        support = uniq.astype(np.float32)
        support_probs = (cnt.astype(np.float64) / max(float(cnt.sum()), 1.0))
        median = float(np.nanmedian(x_obs))
        mean = float(np.nanmean(x_obs))
        std = float(np.nanstd(x_obs))

    support_n = int(support.size)
    is_low = _is_low_card_candidate(col, support_n, obs_n)
    pos_rate = float(np.mean(x_obs > 0)) if obs_n else 0.0
    is_sparse = bool(pos_rate < 0.05 and _domain_nonnegative(col))

    # Transitions and runs from observed TRAIN sequence only; missing values break runs.
    transitions: Dict[float, List[float]] = defaultdict(list)
    run_vals: List[float] = []
    run_lens: List[int] = []
    last = None; run_len = 0
    prev = None
    for v in x_full:
        if not np.isfinite(v):
            if last is not None:
                run_vals.append(float(last)); run_lens.append(int(run_len))
            last = None; run_len = 0; prev = None
            continue
        vv = float(np.round(v, 6))
        if prev is not None:
            transitions[float(prev)].append(vv)
        prev = vv
        if last is None or vv != float(last):
            if last is not None:
                run_vals.append(float(last)); run_lens.append(int(run_len))
            last = vv; run_len = 1
        else:
            run_len += 1
    if last is not None:
        run_vals.append(float(last)); run_lens.append(int(run_len))

    trans_vals: Dict[float, np.ndarray] = {}
    trans_probs: Dict[float, np.ndarray] = {}
    for k, vals in transitions.items():
        u, c = np.unique(np.asarray(vals, dtype=np.float64), return_counts=True)
        trans_vals[k] = u.astype(np.float32)
        trans_probs[k] = c.astype(np.float64) / max(float(c.sum()), 1.0)

    return TrainFit(
        col=col,
        entity=_infer_entity(col),
        family=_family_for_col(col),
        subfamily=_subfamily_for_col(col),
        field=_field_name(col),
        train_full=x_full,
        train_obs=x_obs,
        val_mask=val_mask,
        obs_n=obs_n,
        obs_rate=obs_rate,
        median=median,
        mean=mean,
        std=std,
        q001=q["q001"], q005=q["q005"], q01=q["q01"], q05=q["q05"], q10=q["q10"],
        q50=q["q50"], q90=q["q90"], q95=q["q95"], q99=q["q99"], q995=q["q995"], q999=q["q999"],
        clip_lo=q["q001"], clip_hi=q["q999"],
        support=support, support_probs=support_probs, support_n=support_n,
        is_low_card=is_low, is_sparse=is_sparse, positive_rate=pos_rate,
        transitions=trans_vals, transition_probs=trans_probs,
        run_values=np.asarray(run_vals, dtype=np.float32),
        run_lengths=np.asarray(run_lens, dtype=np.int32),
    )

