def _sparse_event_accumulator(fit: TrainFit, n: int, rng: np.random.Generator) -> np.ndarray:
    if fit.obs_n == 0:
        return _nan_array(n)
    pos = fit.train_obs[fit.train_obs > 0]
    if pos.size == 0:
        return np.zeros(int(n), dtype=np.float32)
    rate = min(max(float(pos.size) / max(float(fit.obs_n), 1.0), 0.0), 1.0)
    active = rng.random(int(n)) < rate
    y = np.zeros(int(n), dtype=np.float32)
    y[active] = rng.choice(pos.astype(np.float32), size=int(active.sum()), replace=True)
    return _postprocess(fit.col, y, fit)


def _sparse_precip_event_replay_v2(fit: TrainFit, n: int, rng: np.random.Generator) -> np.ndarray:
    if fit.obs_n == 0:
        return _nan_array(n)
    pos = fit.train_obs[np.isfinite(fit.train_obs) & (fit.train_obs > 0)]
    y = np.zeros(int(n), dtype=np.float32)
    if pos.size == 0:
        return _postprocess(fit.col, y, fit)
    event_rate = min(max(float(pos.size) / max(float(fit.obs_n), 1.0), 0.0), 1.0)
    active = rng.random(int(n)) < event_rate
    if active.any():
        y[active] = rng.choice(pos.astype(np.float32), size=int(active.sum()), replace=True)
    return _postprocess(fit.col, y, fit)


def _sparse_precip_daily_accumulator_v2(fit: TrainFit, n: int, rng: np.random.Generator) -> np.ndarray:
    if fit.obs_n == 0:
        return _nan_array(n)
    x = fit.train_obs.astype(np.float64)
    x = x[np.isfinite(x)]
    if x.size == 0:
        return _nan_array(n)
    diffs = np.diff(x) if x.size > 1 else np.array([], dtype=np.float64)
    inc = diffs[diffs > 1e-9]
    reset_rate = float(np.mean(diffs < -1e-9)) if diffs.size else 0.0
    plateau_rate = float(np.mean(np.abs(diffs) <= 1e-9)) if diffs.size else 0.80
    support = fit.support.astype(np.float32)
    probs = fit.support_probs.astype(np.float64)
    probs = probs / max(float(probs.sum()), 1e-12)
    y = np.empty(int(n), dtype=np.float32)
    state = float(rng.choice(support, p=probs))
    for i in range(int(n)):
        y[i] = np.float32(state)
        if rng.random() < min(reset_rate, 0.10):
            state = float(np.min(support))
        elif inc.size and rng.random() > plateau_rate:
            state = state + float(rng.choice(inc))
            state = min(state, float(fit.q999))
        else:
            state = state
    y = _project_to_support(y, support) if fit.support_n <= int(CFG.get("cell12c2_precip_accumulator_support_project_max", 512)) else y
    return _postprocess(fit.col, y, fit)


def _counter_cycle(fit: TrainFit, n: int, rng: np.random.Generator) -> np.ndarray:
    if _is_counter_progression_publication_guard_col_12c2(fit.col):
        return _counter_progression_v3_lawful(fit, n, rng)
    if fit.obs_n == 0:
        return _nan_array(n)
    x = _context_piecewise_replay(fit, n, rng)
    # Keep counters monotone within local cycles when TRAIN mostly monotone.
    finite = np.isfinite(x)
    if finite.sum() > 2:
        diffs = np.diff(fit.train_obs.astype(np.float64)) if fit.train_obs.size > 2 else np.array([])
        monotone_frac = float(np.mean(diffs >= -1e-6)) if diffs.size else 0.0
        if monotone_frac >= 0.80:
            vals = np.maximum.accumulate(x[finite])
            # Allow reset if TRAIN has resets.
            reset_rate = float(np.mean(diffs < -1e-6)) if diffs.size else 0.0
            if reset_rate > 0:
                reset = rng.random(vals.size) < min(reset_rate, 0.01)
                for i in np.where(reset)[0]:
                    vals[i:] = vals[i:] - vals[i] + fit.q05
                    vals = np.maximum(vals, fit.q001)
            x[finite] = vals.astype(np.float32)
    return _postprocess(fit.col, x, fit)


def _power_episode(fit: TrainFit, n: int, rng: np.random.Generator) -> np.ndarray:
    # Avoid interpolated phantom states for smart plug current/consumption: use
    # empirical support/dwell when support is discrete; otherwise piecewise replay.
    if fit.is_low_card or fit.support_n <= 128:
        return _lowcard_semimarkov(fit, n, rng)
    return _context_piecewise_replay(fit, n, rng)


def _power_cumulative_consumption_cycle(fit: TrainFit, n: int, rng: np.random.Generator) -> np.ndarray:
    """
    TRAIN-only cumulative consumption generator.

    Purpose:
    - Preserve exact TRAIN support/grid where the signal is quantized.
    - Preserve plateau-heavy behavior.
    - Allow reset/cycle behavior if observed in TRAIN.
    - Avoid interpolated phantom consumption states.
    """
    if fit.obs_n == 0:
        return _nan_array(n)

    x = fit.train_obs.astype(np.float64)
    x = x[np.isfinite(x)]
    if x.size == 0:
        return _nan_array(n)

    # If support is small/quantized, generate directly on support.
    support = fit.support.astype(np.float32)
    probs = fit.support_probs.astype(np.float64)
    probs = probs / max(float(probs.sum()), 1e-12)

    # Estimate empirical dwell lengths by support state.
    run_vals = fit.run_values.astype(np.float32) if fit.run_values.size else support
    run_lens = fit.run_lengths.astype(np.int32) if fit.run_lengths.size else np.ones_like(support, dtype=np.int32)
    run_lens = np.clip(run_lens, 1, max(2, int(np.nanpercentile(run_lens, 95)) if run_lens.size else 2))

    # Estimate reset probability from observed TRAIN differences.
    diffs = np.diff(x) if x.size > 2 else np.array([], dtype=np.float64)
    reset_rate = float(np.mean(diffs < -1e-9)) if diffs.size else 0.0
    increase_rate = float(np.mean(diffs > 1e-9)) if diffs.size else 0.0

    y = np.empty(int(n), dtype=np.float32)
    state = float(rng.choice(support, p=probs))
    i = 0

    while i < n:
        L = int(rng.choice(run_lens)) if run_lens.size else 1
        L = max(1, min(L, n - i))
        y[i:i + L] = np.float32(state)
        i += L

        if reset_rate > 0 and rng.random() < min(reset_rate, 0.05):
            state = float(rng.choice(support[: max(1, min(3, support.size))]))
            continue

        if increase_rate > 0 and rng.random() < increase_rate:
            higher = support[support >= state - 1e-6]
            if higher.size:
                local_probs = np.ones(higher.size, dtype=np.float64)
                local_probs = local_probs / local_probs.sum()
                state = float(rng.choice(higher, p=local_probs))
            else:
                state = float(rng.choice(support, p=probs))
        else:
            state = float(rng.choice(support, p=probs))

    y = _project_to_support(y, support)
    return _postprocess(fit.col, y, fit)


def _power_cumulative_consumption_cycle_v2(fit: TrainFit, n: int, rng: np.random.Generator) -> np.ndarray:
    if fit.obs_n == 0:
        return _nan_array(n)
    x = fit.train_obs.astype(np.float64)
    x = x[np.isfinite(x)]
    if x.size == 0:
        return _nan_array(n)
    support = fit.support.astype(np.float32)
    probs = fit.support_probs.astype(np.float64)
    probs = probs / max(float(probs.sum()), 1e-12)
    diffs = np.diff(x) if x.size > 1 else np.array([], dtype=np.float64)
    increments = diffs[diffs > 1e-9]
    reset_rate = float(np.mean(diffs < -1e-9)) if diffs.size else 0.0
    plateau_lens = fit.run_lengths.astype(np.int32) if fit.run_lengths.size else np.array([1], dtype=np.int32)
    plateau_lens = np.clip(
        plateau_lens,
        1,
        max(2, int(np.nanpercentile(plateau_lens, 95)) if plateau_lens.size else 2),
    )
    y = np.empty(int(n), dtype=np.float32)
    state = float(rng.choice(support, p=probs))
    i = 0
    while i < n:
        L = int(rng.choice(plateau_lens)) if plateau_lens.size else 1
        L = max(1, min(L, n - i))
        y[i:i + L] = np.float32(state)
        i += L
        if reset_rate > 0 and rng.random() < min(reset_rate, 0.05):
            state = float(rng.choice(support[: max(1, min(5, support.size))]))
        elif increments.size:
            state = min(state + float(rng.choice(increments)), float(fit.q999))
        else:
            state = float(rng.choice(support, p=probs))
    y = _project_to_support(y, support)
    y = np.maximum(y, 0.0)
    return _postprocess(fit.col, y, fit)
    
def _s5_maintenance(fit: TrainFit, n: int, rng: np.random.Generator) -> np.ndarray:
    if "time_left" in fit.col.lower():
        y = _context_piecewise_replay(fit, n, rng)
        # Time-left signals often decay during an episode; retain train support.
        return _postprocess(fit.col, y, fit)
    if fit.is_low_card or fit.is_sparse:
        return _lowcard_semimarkov(fit, n, rng)
    return _context_piecewise_replay(fit, n, rng)


def _s5_maintenance_plateau_v7(fit: TrainFit, n: int, rng: np.random.Generator) -> np.ndarray:
    if fit.obs_n == 0:
        return _nan_array(n)
    support = fit.support.astype(np.float32)
    probs = fit.support_probs.astype(np.float64)
    probs = probs / max(float(probs.sum()), 1e-12)
    lens = fit.run_lengths.astype(np.int32) if fit.run_lengths.size else np.array([1], dtype=np.int32)
    clip_q = 99 if "time_left" in fit.col.lower() or "life" in fit.col.lower() else 95
    lens = np.clip(lens, 1, max(2, int(np.nanpercentile(lens, clip_q)) if lens.size else 2))
    y = np.empty(int(n), dtype=np.float32)
    state = float(rng.choice(support, p=probs))
    i = 0
    while i < n:
        L = int(rng.choice(lens)) if lens.size else 1
        L = max(1, min(L, n - i))
        y[i:i + L] = np.float32(state)
        i += L
        key = float(np.round(state, 6))
        if key in fit.transitions and rng.random() >= 0.10:
            nxt = fit.transitions[key].astype(np.float32)
            nxt_probs = fit.transition_probs[key].astype(np.float64)
            nxt_probs = nxt_probs / max(float(nxt_probs.sum()), 1e-12)
            state = float(rng.choice(nxt, p=nxt_probs))
        else:
            state = float(rng.choice(support, p=probs))
    y = _project_to_support(np.maximum(y, 0.0), support)
    return _postprocess(fit.col, y, fit)


def _s5_maintenance_event_boundary_v7(fit: TrainFit, n: int, rng: np.random.Generator) -> np.ndarray:
    if fit.obs_n == 0:
        return _nan_array(n)
    support = fit.support.astype(np.float32)
    probs = fit.support_probs.astype(np.float64)
    probs = probs / max(float(probs.sum()), 1e-12)
    x = fit.train_obs.astype(np.float64)
    diffs = np.diff(x) if x.size > 1 else np.array([], dtype=np.float64)
    downward = diffs[diffs < -1e-9]
    upward = diffs[diffs > 1e-9]
    reset_like_rate = float(np.mean(diffs < -1e-9)) if diffs.size else 0.0
    y = np.empty(int(n), dtype=np.float32)
    state = float(rng.choice(support, p=probs))
    lens = fit.run_lengths.astype(np.int32) if fit.run_lengths.size else np.array([1], dtype=np.int32)
    lens = np.clip(lens, 1, max(2, int(np.nanpercentile(lens, 95)) if lens.size else 2))
    i = 0
    while i < n:
        L = int(rng.choice(lens)) if lens.size else 1
        L = max(1, min(L, n - i))
        y[i:i + L] = np.float32(state)
        i += L
        if ("time_left" in fit.col.lower() or "life" in fit.col.lower()) and downward.size:
            if reset_like_rate > 0 and rng.random() < min(reset_like_rate, 0.08):
                state = float(rng.choice(support, p=probs))
            else:
                state = max(float(np.min(support)), state + float(rng.choice(downward)))
        elif upward.size:
            state = min(float(np.max(support)), state + float(rng.choice(upward)))
        else:
            state = float(rng.choice(support, p=probs))
    y = _project_to_support(np.maximum(y, 0.0), support)
    return _postprocess(fit.col, y, fit)


def _withings_session(fit: TrainFit, n: int, rng: np.random.Generator) -> np.ndarray:
    # Night-session summary values are low frequency and often state-like. Preserve
    # dwell/session structure from TRAIN without replaying full aligned blocks.
    if fit.is_low_card or fit.support_n <= 256:
        return _lowcard_semimarkov(fit, n, rng)
    return _context_piecewise_replay(fit, n, rng)


def _motion_axis(fit: TrainFit, n: int, rng: np.random.Generator) -> np.ndarray:
    y = _context_piecewise_replay(fit, n, rng)
    if fit.std > 1e-6 and not fit.is_low_card:
        y = y + rng.normal(0.0, 0.02 * fit.std, size=int(n)).astype(np.float32)
    return _postprocess(fit.col, y, fit)


def _negative_binomial(fit: TrainFit, n: int, rng: np.random.Generator) -> np.ndarray:
    x = fit.train_obs[fit.train_obs >= 0]
    if x.size == 0:
        return np.zeros(int(n), dtype=np.float32)
    mu = float(np.mean(x)); var = float(np.var(x))
    if var <= mu + 1e-9:
        y = rng.poisson(max(mu, 0.0), size=int(n)).astype(np.float32)
    else:
        # Gamma-Poisson / negative-binomial parameterization.
        r = max(mu * mu / (var - mu), 1e-6)
        p = r / (r + mu)
        y = rng.negative_binomial(r, p, size=int(n)).astype(np.float32)
    return _postprocess(fit.col, y, fit)

# ----------------------------------------------------------
# 5. Copula and sequence generators
# ----------------------------------------------------------
def _normal_scores(x: np.ndarray) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
    # Robust empirical Gaussianization using TRAIN only.
    vals = _finite_np(x)
    if vals.size == 0:
        return np.zeros_like(x, dtype=np.float32), np.array([0.0]), np.array([0.0])
    xs = np.sort(vals.astype(np.float64))
    ranks = np.searchsorted(xs, x.astype(np.float64), side="right")
    u = (ranks + 0.5) / (len(xs) + 1.0)
    u = np.clip(u, 1e-4, 1 - 1e-4)
    try:
        from scipy.stats import norm
        z = norm.ppf(u).astype(np.float32)
    except Exception:
        # Logistic approximation is good enough for a fallback if scipy is absent.
        z = (np.log(u / (1 - u)) / 1.702).astype(np.float32)
    return z, xs.astype(np.float32), np.linspace(0, 1, len(xs), dtype=np.float32)


def _fit_sample_gaussian_copula(cols: List[str], n: int) -> Dict[str, np.ndarray]:
    cols = [c for c in cols if c in TRAIN_FIT and TRAIN_FIT[c].obs_n >= MIN_TRAIN_OBS]
    if not cols:
        return {}
    # Use rowwise TRAIN matrix with median imputation; fitted only on TRAIN.
    X = []
    marginals = {}
    for c in cols:
        fit = TRAIN_FIT[c]
        x = fit.train_full.astype(np.float32).copy()
        x[~np.isfinite(x)] = fit.median
        z, xs, _ = _normal_scores(x)
        X.append(z)
        marginals[c] = xs
    Z = np.vstack(X).T.astype(np.float64)
    if Z.shape[0] > int(CFG.get("cell12c2_copula_train_row_cap", 100000)):
        rng = _rng_for("copula_rows", len(cols), Z.shape[0])
        idx = rng.choice(Z.shape[0], size=int(CFG.get("cell12c2_copula_train_row_cap", 100000)), replace=False)
        Z = Z[idx]
    corr = np.corrcoef(Z, rowvar=False)
    corr = np.nan_to_num(corr, nan=0.0, posinf=0.0, neginf=0.0)
    if corr.ndim == 0:
        corr = np.array([[1.0]])
    shrink = float(CFG.get("cell12c2_copula_corr_shrink", 0.03))
    corr = (1.0 - shrink) * corr + shrink * np.eye(len(cols))
    corr = (corr + corr.T) / 2.0
    vals, vecs = np.linalg.eigh(corr)
    vals = np.clip(vals, 1e-6, None)
    corr = (vecs @ np.diag(vals) @ vecs.T).astype(np.float64)
    rng = _rng_for("gaussian_copula", "|".join(cols), n)
    Zs = rng.multivariate_normal(np.zeros(len(cols)), corr, size=int(n)).astype(np.float64)
    try:
        from scipy.stats import norm
        U = norm.cdf(Zs)
    except Exception:
        U = 1.0 / (1.0 + np.exp(-1.702 * Zs))
    out = {}
    for j, c in enumerate(cols):
        xs = marginals[c]
        q = np.linspace(0.0, 1.0, len(xs), dtype=np.float64)
        y = np.interp(np.clip(U[:, j], 0, 1), q, xs).astype(np.float32)
        out[c] = _postprocess(c, y, TRAIN_FIT[c])
    return out

SEQUENCE_FIT_SUMMARY_ROWS: List[Dict[str, Any]] = []
SEQUENCE_VAL_CACHE: Dict[Tuple[str, str], np.ndarray] = {}
WITHINGS_JOINT_SESSION_VAL_CACHE: Dict[Tuple[str, str], np.ndarray] = {}


def _sequence_eligible_cols(cols: Iterable[str]) -> List[str]:
    """
    Sequence candidates are expensive and scientifically meaningful only for
    dense continuous columns with enough support and no obvious discrete/sparse/
    counter/telemetry semantics.

    If this returns zero columns, DDPM/TimeGAN rows must not appear in the route.
    """
    out: List[str] = []
    for c in cols:
        fit = TRAIN_FIT[c]
        desc = _semantic_descriptor_12c2(c)

        if fit.obs_n < SEQUENCE_MIN_OBS_N:
            continue
        if fit.obs_rate < SEQUENCE_MIN_OBS_RATE:
            continue
        if fit.support_n < SEQUENCE_MIN_UNIQUE:
            continue
        if fit.is_low_card or fit.is_sparse:
            continue
        if _is_telemetry_like_lowcard_col(c) or _is_ordinal_state_like_col(c):
            continue
        if _is_counter_like(c) or _is_power_current(c) or _is_s5(c) or _is_withings(c):
            continue
        if _is_pressure(c):
            # quasi-static pressure is handled by pressure-specific candidates,
            # not by sequence neural generators.
            continue
        if _token_hit_12c2(desc, ["state", "mode", "status", "count", "total", "time_left", "remaining"]):
            continue

        # Positive dense-continuous semantics.
        if not (
            _is_environmental(c)
            or _is_motion_axis(c)
            or _token_hit_12c2(desc, ["temperature", "humidity", "illuminance", "purity", "air_quality"])
        ):
            continue

        out.append(c)
    return out


def _materialize_sequence_candidates(generator: str, cols: List[str], n: int) -> None:
    if not ENABLE_SEQUENCE or not cols:
        return
    try:
        import torch
        import torch.nn as nn
        from torch.utils.data import DataLoader, TensorDataset
    except Exception as exc:
        for c in cols:
            SEQUENCE_FIT_SUMMARY_ROWS.append({
                "generator": generator, "col": c, "status": "skipped_torch_unavailable", "reason": str(exc),
                "fit_split": "TRAIN_only", "test_used_for_fitting": False,
            })
        return

    torch.manual_seed(SEED)
    device_name = str(CFG.get("cell12c2_sequence_device", "cuda" if torch.cuda.is_available() else "cpu"))
    if device_name == "cuda" and not torch.cuda.is_available():
        device_name = "cpu"
    device = torch.device(device_name)

    class TinySeqDenoiser(nn.Module):
        def __init__(self, d: int, h: int):
            super().__init__()
            self.net = nn.Sequential(nn.Linear(d + 1, h), nn.SiLU(), nn.Linear(h, h), nn.SiLU(), nn.Linear(h, d))
        def forward(self, x, t):
            tt = t.float().view(-1, 1, 1).expand(x.shape[0], x.shape[1], 1)
            return self.net(torch.cat([x, tt], dim=-1))

    class TinySeqGAN(nn.Module):
        def __init__(self, d: int, h: int):
            super().__init__()
            self.rnn = nn.GRU(d, h, batch_first=True)
            self.out = nn.Linear(h, d)
        def forward(self, z):
            o, _ = self.rnn(z)
            return self.out(o)

    class TinyDisc(nn.Module):
        def __init__(self, d: int, h: int):
            super().__init__()
            self.rnn = nn.GRU(d, h, batch_first=True)
            self.out = nn.Linear(h, 1)
        def forward(self, x):
            o, _ = self.rnn(x)
            return self.out(o[:, -1, :]).squeeze(-1)

    for start in range(0, len(cols), SEQUENCE_GROUP_SIZE):
        group = cols[start:start + SEQUENCE_GROUP_SIZE]
        # TRAIN-only matrix, robust scaled.
        X_cols = []
        med = []; scale = []
        for c in group:
            fit = TRAIN_FIT[c]
            x = fit.train_full.astype(np.float32).copy()
            x[~np.isfinite(x)] = fit.median
            q75, q25 = np.percentile(fit.train_obs, [75, 25]) if fit.obs_n else (1.0, 0.0)
            sc = float(q75 - q25)
            if not np.isfinite(sc) or sc <= 1e-6:
                sc = max(float(fit.std), 1.0)
            X_cols.append(((x - fit.median) / sc).astype(np.float32))
            med.append(float(fit.median)); scale.append(float(sc))
        X = np.vstack(X_cols).T.astype(np.float32)
        if X.shape[0] > SEQUENCE_TRAIN_ROW_CAP:
            rr = _rng_for("sequence_row_cap", generator, "|".join(group), X.shape[0])
            start_idx = int(rr.integers(0, max(1, X.shape[0] - SEQUENCE_TRAIN_ROW_CAP + 1)))
            X = X[start_idx:start_idx + SEQUENCE_TRAIN_ROW_CAP]
        windows = []
        for i in range(0, max(1, X.shape[0] - SEQUENCE_LEN + 1), max(1, SEQUENCE_STRIDE)):
            w = X[i:i + SEQUENCE_LEN]
            if w.shape[0] == SEQUENCE_LEN:
                windows.append(w)
            if len(windows) >= SEQUENCE_MAX_WINDOWS:
                break
        if not windows:
            for c in group:
                SEQUENCE_FIT_SUMMARY_ROWS.append({"generator": generator, "col": c, "status": "skipped_no_windows", "fit_split": "TRAIN_only", "test_used_for_fitting": False})
            continue
        W = np.stack(windows).astype(np.float32)
        loader = DataLoader(TensorDataset(torch.from_numpy(W)), batch_size=SEQUENCE_BATCH_SIZE, shuffle=True, drop_last=False)
        d = W.shape[-1]
        losses = []
        if generator == "DDPM_conditional_sequence":
            model = TinySeqDenoiser(d, SEQUENCE_HIDDEN).to(device)
            opt = torch.optim.AdamW(model.parameters(), lr=SEQUENCE_LR)
            for ep in range(max(1, DDPM_EPOCHS)):
                ep_losses = []
                for (xb,) in loader:
                    xb = xb.to(device)
                    t = torch.rand(xb.shape[0], device=device)
                    noise = torch.randn_like(xb)
                    alpha = (1.0 - 0.9 * t).view(-1, 1, 1)
                    xt = alpha * xb + torch.sqrt(torch.clamp(1.0 - alpha ** 2, min=1e-6)) * noise
                    pred = model(xt, t)
                    loss = torch.mean((pred - noise) ** 2)
                    opt.zero_grad(); loss.backward(); opt.step()
                    ep_losses.append(float(loss.detach().cpu()))
                losses.append(float(np.mean(ep_losses)) if ep_losses else np.nan)
            # Sampling: seed from random TRAIN windows and denoise for compact steps.
            rr = _rng_for("ddpm_sample", "|".join(group), n)
            out_chunks = []
            while sum(x.shape[0] for x in out_chunks) < n:
                base = W[rr.integers(0, W.shape[0], size=1)][0]
                xb = torch.from_numpy(base[None, :, :]).float().to(device)
                xb = xb + 0.25 * torch.randn_like(xb)
                with torch.no_grad():
                    for step in range(max(4, min(DDPM_STEPS, 64)), 0, -1):
                        t = torch.full((1,), step / max(DDPM_STEPS, 1), device=device)
                        eps = model(xb, t)
                        xb = xb - 0.08 * eps
                out_chunks.append(xb.detach().cpu().numpy()[0])
            Y = np.concatenate(out_chunks, axis=0)[:n, :]
        else:
            gen = TinySeqGAN(d, SEQUENCE_HIDDEN).to(device)
            disc = TinyDisc(d, SEQUENCE_HIDDEN).to(device)
            opt_g = torch.optim.AdamW(gen.parameters(), lr=SEQUENCE_LR)
            opt_d = torch.optim.AdamW(disc.parameters(), lr=SEQUENCE_LR)
            bce = nn.BCEWithLogitsLoss()
            for ep in range(max(1, TIMEGAN_EPOCHS)):
                ep_losses = []
                for (xb,) in loader:
                    xb = xb.to(device)
                    z = torch.randn_like(xb)
                    fake = gen(z).detach()
                    d_loss = bce(disc(xb), torch.ones(xb.shape[0], device=device)) + bce(disc(fake), torch.zeros(xb.shape[0], device=device))
                    opt_d.zero_grad(); d_loss.backward(); opt_d.step()
                    z = torch.randn_like(xb)
                    fake = gen(z)
                    # supervised moment loss stabilizes tiny GAN and avoids mode explosion.
                    g_loss = bce(disc(fake), torch.ones(xb.shape[0], device=device)) + 0.05 * (fake.mean() - xb.mean()).abs() + 0.05 * (fake.std() - xb.std()).abs()
                    opt_g.zero_grad(); g_loss.backward(); opt_g.step()
                    ep_losses.append(float(g_loss.detach().cpu()))
                losses.append(float(np.mean(ep_losses)) if ep_losses else np.nan)
            out_chunks = []
            while sum(x.shape[0] for x in out_chunks) < n:
                bs = 1
                z = torch.randn((bs, SEQUENCE_LEN, d), device=device)
                with torch.no_grad():
                    out_chunks.append(gen(z).detach().cpu().numpy()[0])
            Y = np.concatenate(out_chunks, axis=0)[:n, :]

        med_arr = np.asarray(med, dtype=np.float32)
        sc_arr = np.asarray(scale, dtype=np.float32)
        Y = Y.astype(np.float32) * sc_arr[None, :] + med_arr[None, :]
        for j, c in enumerate(group):
            SEQUENCE_VAL_CACHE[(generator, c)] = _postprocess(c, Y[:, j], TRAIN_FIT[c])
            SEQUENCE_FIT_SUMMARY_ROWS.append({
                "generator": generator, "col": c, "cols_in_group": "|".join(group), "status": "materialized",
                "train_windows": int(W.shape[0]), "sequence_len": int(SEQUENCE_LEN), "epochs": int(DDPM_EPOCHS if generator.startswith("DDPM") else TIMEGAN_EPOCHS),
                "final_loss": float(losses[-1]) if losses else np.nan, "loss_trace": "|".join(f"{x:.6f}" for x in losses if np.isfinite(x)),
                "device": str(device), "fit_split": "TRAIN_only", "val_used_for_fitting": False, "test_used_for_fitting": False,
            })
        del W, loader
        if device.type == "cuda":
            torch.cuda.empty_cache()
        gc.collect()


def _build_withings_joint_session_cache_12c2(cols: List[str], n: int) -> None:
    if not cols:
        return
    groups: Dict[str, List[str]] = defaultdict(list)
    for c in cols:
        groups[TRAIN_FIT[c].entity].append(c)

    for entity, group_cols in groups.items():
        group_cols = [c for c in group_cols if c in TRAIN_FIT and TRAIN_FIT[c].obs_n >= MIN_TRAIN_OBS]
        if not group_cols:
            continue
        train_mat = df_tr[group_cols].apply(pd.to_numeric, errors="coerce").to_numpy(dtype=np.float32, copy=True)
        observed_rows = np.flatnonzero(np.isfinite(train_mat).any(axis=1))
        if observed_rows.size == 0:
            continue
        rng = _rng_for("withings_joint_session_v2", entity, "|".join(group_cols), n)
        sampled_rows = rng.choice(observed_rows, size=int(n), replace=True)
        sampled = train_mat[sampled_rows, :]
        for j, c in enumerate(group_cols):
            fit = TRAIN_FIT[c]
            y = sampled[:, j].astype(np.float32)
            missing = ~np.isfinite(y)
            if missing.any():
                y[missing] = rng.choice(fit.support, size=int(missing.sum()), replace=True, p=fit.support_probs).astype(np.float32)
            if _should_project_to_train_support_12c2(c, fit):
                y = _project_to_support(y, fit.support)
            WITHINGS_JOINT_SESSION_VAL_CACHE[("WithingsJointNightSessionSummaryGeneratorV2", c)] = _postprocess(c, y, fit)


def _build_withings_joint_session_coherence_v6_cache_12c2(cols: List[str], n: int) -> None:
    if not cols:
        return
    groups: Dict[str, List[str]] = defaultdict(list)
    for c in cols:
        groups[TRAIN_FIT[c].entity].append(c)
    for entity, group_cols in groups.items():
        group_cols = [c for c in group_cols if c in TRAIN_FIT and TRAIN_FIT[c].obs_n >= MIN_TRAIN_OBS]
        if not group_cols:
            continue
        train_mat = df_tr[group_cols].apply(pd.to_numeric, errors="coerce").to_numpy(dtype=np.float32, copy=True)
        observed_rows = np.flatnonzero(np.isfinite(train_mat).any(axis=1))
        if observed_rows.size == 0:
            continue
        complete_score = np.isfinite(train_mat[observed_rows, :]).sum(axis=1).astype(np.float64)
        weights = np.maximum(complete_score, 1.0)
        weights = weights / max(float(weights.sum()), 1e-12)
        rng = _rng_for("withings_joint_session_v6", entity, "|".join(group_cols), n)
        sampled_rows = rng.choice(observed_rows, size=int(n), replace=True, p=weights)
        sampled = train_mat[sampled_rows, :]
        for j, c in enumerate(group_cols):
            fit = TRAIN_FIT[c]
            y = sampled[:, j].astype(np.float32)
            missing = ~np.isfinite(y)
            if missing.any():
                if _withings_field_kind_12c2(c) == "count":
                    imputed = _withings_session_count_dwell_v5(fit, int(missing.sum()), rng)
                else:
                    imputed = rng.choice(fit.support, size=int(missing.sum()), replace=True, p=fit.support_probs).astype(np.float32)
                y[missing] = imputed
            if _withings_field_kind_12c2(c) == "count":
                y = np.round(y).astype(np.float32)
            if _should_project_to_train_support_12c2(c, fit):
                y = _project_to_support(y, fit.support)
            WITHINGS_JOINT_SESSION_VAL_CACHE[("WithingsJointSessionCoherenceV6_train_only", c)] = _postprocess(c, y, fit)


def _build_withings_joint_session_coherence_v7_cache_12c2(cols: List[str], n: int) -> None:
    if not cols:
        return
    groups: Dict[str, List[str]] = defaultdict(list)
    for c in cols:
        groups[TRAIN_FIT[c].entity].append(c)
    for entity, group_cols in groups.items():
        group_cols = [c for c in group_cols if c in TRAIN_FIT and TRAIN_FIT[c].obs_n >= MIN_TRAIN_OBS]
        if not group_cols:
            continue
        train_mat = df_tr[group_cols].apply(pd.to_numeric, errors="coerce").to_numpy(dtype=np.float32, copy=True)
        observed_rows = np.flatnonzero(np.isfinite(train_mat).any(axis=1))
        if observed_rows.size == 0:
            continue
        rng = _rng_for("withings_joint_session_v7", entity, "|".join(group_cols), n)
        med = np.asarray([TRAIN_FIT[c].median for c in group_cols], dtype=np.float32)
        scale = np.asarray([max(float(TRAIN_FIT[c].std), 1.0) for c in group_cols], dtype=np.float32)
        X = train_mat.astype(np.float32).copy()
        finite = np.isfinite(X)
        X[~finite] = np.take(med, np.where(~finite)[1])
        Z = (X - med[None, :]) / scale[None, :]
        Z_obs = Z[observed_rows, :]
        if Z_obs.shape[0] >= 3 and Z_obs.shape[1] >= 2:
            centered = Z_obs - np.nanmean(Z_obs, axis=0, keepdims=True)
            try:
                _, s, vt = np.linalg.svd(centered, full_matrices=False)
                rank = max(1, min(int(np.sum(s > 1e-6)), min(4, vt.shape[0])))
                coeff = rng.normal(0.0, 1.0, size=(int(n), rank)).astype(np.float32)
                component_scale = (s[:rank] / math.sqrt(max(Z_obs.shape[0] - 1, 1))).astype(np.float32)
                latent = coeff * component_scale[None, :]
                sampled_center = Z_obs[rng.choice(np.arange(Z_obs.shape[0]), size=int(n), replace=True), :]
                Yz = sampled_center + 0.35 * (latent @ vt[:rank, :].astype(np.float32))
            except Exception:
                Yz = Z_obs[rng.choice(np.arange(Z_obs.shape[0]), size=int(n), replace=True), :]
        else:
            Yz = Z_obs[rng.choice(np.arange(Z_obs.shape[0]), size=int(n), replace=True), :]
        Y = (Yz.astype(np.float32) * scale[None, :]) + med[None, :]

        pattern_rows = observed_rows[rng.choice(np.arange(observed_rows.size), size=int(n), replace=True)]
        patterns = np.isfinite(train_mat[pattern_rows, :]) & (np.abs(train_mat[pattern_rows, :]) > 1e-6)
        kinds = [_withings_field_kind_12c2(c) for c in group_cols]
        duration_idx = [j for j, k in enumerate(kinds) if k == "sleep_stage_summary" and "count" not in _norm_txt_12c2(TRAIN_FIT[group_cols[j]].field)]
        for j, c in enumerate(group_cols):
            fit = TRAIN_FIT[c]
            y = Y[:, j].astype(np.float32)
            if kinds[j] == "count":
                y = _project_to_support(np.round(np.maximum(y, 0.0)).astype(np.float32), np.unique(np.round(fit.support).astype(np.float32)))
                zero_mask = ~patterns[:, j]
                if zero_mask.any() and np.any(np.isclose(fit.support.astype(np.float64), 0.0, atol=1e-6)):
                    y[zero_mask] = 0.0
            else:
                if _domain_nonnegative(c):
                    y = np.maximum(y, 0.0).astype(np.float32)
                if duration_idx and j in duration_idx:
                    train_max = float(np.nanmax(fit.train_obs)) if fit.obs_n else np.nan
                    if np.isfinite(train_max):
                        y = np.minimum(y, train_max).astype(np.float32)
                if _should_project_to_train_support_12c2(c, fit):
                    y = _project_to_support(y, fit.support)
            WITHINGS_JOINT_SESSION_VAL_CACHE[("WithingsJointSessionCoherenceV7_train_only", c)] = _postprocess(c, y, fit)


def _build_withings_v8_joint_session_cache_12c2(cols: List[str], n: int) -> None:
    if not cols:
        return
    groups: Dict[str, List[str]] = defaultdict(list)
    for c in cols:
        groups[TRAIN_FIT[c].entity].append(c)
    for entity, group_cols in groups.items():
        group_cols = [c for c in group_cols if c in TRAIN_FIT and TRAIN_FIT[c].obs_n >= MIN_TRAIN_OBS]
        if not group_cols:
            continue
        train_mat = df_tr[group_cols].apply(pd.to_numeric, errors="coerce").to_numpy(dtype=np.float32, copy=True)
        observed_rows = np.flatnonzero(np.isfinite(train_mat).any(axis=1))
        if observed_rows.size == 0:
            continue
        active_mask = np.isfinite(train_mat).any(axis=1)
        active_runs = _state_run_table_12c2(active_mask.astype(np.float32))
        active_lens = (
            pd.to_numeric(active_runs.loc[active_runs["state"].astype(float).eq(1.0), "length"], errors="coerce")
            .dropna()
            .astype(int)
            .to_numpy()
            if len(active_runs) else np.array([], dtype=np.int32)
        )
        inactive_lens = (
            pd.to_numeric(active_runs.loc[active_runs["state"].astype(float).eq(0.0), "length"], errors="coerce")
            .dropna()
            .astype(int)
            .to_numpy()
            if len(active_runs) else np.array([], dtype=np.int32)
        )
        active_lens = active_lens[active_lens > 0] if active_lens.size else np.array([1], dtype=np.int32)
        inactive_lens = inactive_lens[inactive_lens > 0] if inactive_lens.size else np.array([1], dtype=np.int32)
        completeness = np.isfinite(train_mat[observed_rows, :]).sum(axis=1).astype(np.float64)
        weights = np.maximum(completeness, 1.0)
        weights = weights / max(float(weights.sum()), 1e-12)
        med = np.asarray([TRAIN_FIT[c].median for c in group_cols], dtype=np.float32)
        scale = np.asarray([max(float(TRAIN_FIT[c].std), 1.0) for c in group_cols], dtype=np.float32)
        X = train_mat.astype(np.float32).copy()
        finite = np.isfinite(X)
        X[~finite] = np.take(med, np.where(~finite)[1])
        Z = (X - med[None, :]) / scale[None, :]
        Z_obs = Z[observed_rows, :]
        rng_base = _rng_for("withings_v8_joint_session", entity, "|".join(group_cols), n)

        generated_active = np.zeros(int(n), dtype=bool)
        pos = 0
        start_active = bool(float(active_mask[np.flatnonzero(np.isfinite(active_mask.astype(float)))[0]]) if active_mask.size else True)
        state_active = start_active if rng_base.random() < 0.65 else bool(np.mean(active_mask) >= 0.5)
        while pos < int(n):
            lens = active_lens if state_active else inactive_lens
            L = int(rng_base.choice(lens)) if lens.size else 1
            L = max(1, min(L, int(n) - pos))
            generated_active[pos:pos + L] = bool(state_active)
            pos += L
            state_active = not state_active
        if not generated_active.any():
            generated_active[:] = True

        sampled_idx = rng_base.choice(np.arange(observed_rows.size), size=int(n), replace=True, p=weights)
        sampled_rows = observed_rows[sampled_idx]
        sampled = train_mat[sampled_rows, :].astype(np.float32)
        if Z_obs.shape[0] >= 4 and Z_obs.shape[1] >= 2:
            centered = Z_obs - np.nanmean(Z_obs, axis=0, keepdims=True)
            try:
                _, s, vt = np.linalg.svd(centered, full_matrices=False)
                rank = max(1, min(int(np.sum(s > 1e-6)), min(3, vt.shape[0])))
                latent = rng_base.normal(0.0, 0.18, size=(int(n), rank)).astype(np.float32)
                perturb = (latent * (s[:rank] / math.sqrt(max(Z_obs.shape[0] - 1, 1))).astype(np.float32)[None, :]) @ vt[:rank, :].astype(np.float32)
                sampled = sampled.copy()
                missing_sampled = ~np.isfinite(sampled)
                sampled[missing_sampled] = np.take(med, np.where(missing_sampled)[1])
                sampled = sampled + perturb.astype(np.float32) * scale[None, :]
            except Exception:
                pass

        for gen in WITHINGS_V8_GENERATORS_12C2:
            for j, c in enumerate(group_cols):
                fit = TRAIN_FIT[c]
                y = sampled[:, j].astype(np.float32).copy()
                missing = ~np.isfinite(y)
                if missing.any():
                    if _withings_field_kind_12c2(c) == "count":
                        y[missing] = _withings_session_count_snapshot_dwell_v6_12c2(fit, int(missing.sum()), rng_base)
                    elif fit.support_n and fit.support_n <= 512:
                        y[missing] = rng_base.choice(fit.support, size=int(missing.sum()), replace=True, p=fit.support_probs).astype(np.float32)
                    else:
                        y[missing] = fit.median
                if gen == "WithingsSessionCopulaDwellV8_train_only" and fit.std > 1e-6 and not _should_project_to_train_support_12c2(c, fit):
                    y = y + rng_base.normal(0.0, 0.03 * fit.std, size=int(n)).astype(np.float32)
                if gen == "WithingsConditionalFieldBundleV8_train_only":
                    if _withings_field_kind_12c2(c) == "sleep_stage_summary":
                        y = 0.80 * y + 0.20 * fit.median
                    elif _withings_field_kind_12c2(c) == "score":
                        y = np.clip(y, np.nanmin(fit.train_obs), np.nanmax(fit.train_obs)).astype(np.float32)
                if _withings_field_kind_12c2(c) == "count":
                    y = np.round(np.maximum(y, 0.0)).astype(np.float32)
                elif _domain_nonnegative(c):
                    y = np.maximum(y, 0.0).astype(np.float32)
                if _should_project_to_train_support_12c2(c, fit):
                    y = _project_to_support(y, fit.support)
                # Preserve sparse session cadence without ordered row replay.
                if np.any(np.isclose(fit.support.astype(np.float64), 0.0, atol=1e-6)):
                    y[~generated_active] = 0.0
                WITHINGS_JOINT_SESSION_VAL_CACHE[(gen, c)] = _postprocess(c, y, fit)


def _withings_v9_extract_runs_12c2(values: np.ndarray, *, finite_only: bool = True) -> List[np.ndarray]:
    a = np.asarray(values, dtype=np.float32).reshape(-1)
    runs: List[np.ndarray] = []
    start: Optional[int] = None
    for i, v in enumerate(a):
        ok = bool(np.isfinite(v)) if finite_only else True
        if ok and start is None:
            start = int(i)
        if (not ok) and start is not None:
            if i > start:
                runs.append(a[start:i].copy())
            start = None
    if start is not None and len(a) > start:
        runs.append(a[start:].copy())
    return [r[np.isfinite(r)].astype(np.float32) for r in runs if np.isfinite(r).any()]


def _withings_v9_sample_runs_to_length_12c2(
    runs: List[np.ndarray],
    n: int,
    rng: np.random.Generator,
    fallback: np.ndarray,
) -> np.ndarray:
    n = int(n)
    if n <= 0:
        return np.array([], dtype=np.float32)
    clean_runs = [np.asarray(r, dtype=np.float32).reshape(-1) for r in runs if np.asarray(r).size and np.isfinite(r).any()]
    if not clean_runs:
        vals = np.asarray(fallback, dtype=np.float32)
        vals = vals[np.isfinite(vals)]
        if vals.size == 0:
            return np.full(n, np.nan, dtype=np.float32)
        return rng.choice(vals, size=n, replace=True).astype(np.float32)
    out_parts: List[np.ndarray] = []
    while sum(int(x.size) for x in out_parts) < n:
        order = rng.permutation(len(clean_runs))
        for idx in order:
            out_parts.append(clean_runs[int(idx)])
            if sum(int(x.size) for x in out_parts) >= n:
                break
    return np.concatenate(out_parts).astype(np.float32)[:n]


def _withings_v9_bundle_rows_to_length_12c2(
    run_blocks: List[np.ndarray],
    n: int,
    rng: np.random.Generator,
    width: int,
) -> np.ndarray:
    n = int(n)
    clean = [np.asarray(r, dtype=np.float32) for r in run_blocks if np.asarray(r).ndim == 2 and np.asarray(r).shape[0] > 0]
    if not clean:
        return np.full((n, int(width)), np.nan, dtype=np.float32)
    parts: List[np.ndarray] = []
    while sum(int(x.shape[0]) for x in parts) < n:
        order = rng.permutation(len(clean))
        for idx in order:
            parts.append(clean[int(idx)])
            if sum(int(x.shape[0]) for x in parts) >= n:
                break
    return np.vstack(parts).astype(np.float32)[:n, :]


def _withings_v9_temporal_dwell_12c2(fit: TrainFit, n: int, rng: np.random.Generator, mode: str) -> np.ndarray:
    vals = fit.train_obs[np.isfinite(fit.train_obs)].astype(np.float32)
    if vals.size == 0:
        return np.full(int(n), np.nan, dtype=np.float32)
    if mode == "sparse_session_plateau":
        runs = _state_run_table_12c2(fit.train_obs)
        if len(runs):
            lens = pd.to_numeric(runs["length"], errors="coerce").dropna().astype(int).to_numpy()
            states = pd.to_numeric(runs["state"], errors="coerce").to_numpy(dtype=np.float32)
            good = np.isfinite(states) & (lens > 0)
            lens = lens[good] if lens.size else np.array([1], dtype=np.int32)
            states = states[good] if states.size else vals
            if states.size == 0:
                states = vals
                lens = np.array([1], dtype=np.int32)
            parts: List[np.ndarray] = []
            while sum(int(x.size) for x in parts) < int(n):
                j = int(rng.integers(0, max(int(states.size), 1)))
                L = int(lens[min(j, len(lens) - 1)]) if len(lens) else 1
                parts.append(np.full(max(1, L), float(states[min(j, states.size - 1)]), dtype=np.float32))
            y = np.concatenate(parts).astype(np.float32)[:int(n)]
        else:
            y = _withings_v9_sample_runs_to_length_12c2(_withings_v9_extract_runs_12c2(fit.train_obs), n, rng, vals)
    else:
        y = _withings_v9_sample_runs_to_length_12c2(_withings_v9_extract_runs_12c2(fit.train_obs), n, rng, vals)
    if fit.support_n and fit.support_n <= 512:
        y = _project_to_support(y, fit.support)
    return _postprocess(fit.col, y, fit)


def _build_withings_v9_session_run_cache_12c2(cols: List[str], n: int) -> None:
    if not cols:
        return
    groups: Dict[str, List[str]] = defaultdict(list)
    for c in cols:
        if c in TRAIN_FIT:
            groups[TRAIN_FIT[c].entity].append(c)
    for entity, group_cols in groups.items():
        group_cols = [c for c in sorted(set(group_cols)) if c in TRAIN_FIT and TRAIN_FIT[c].obs_n >= MIN_TRAIN_OBS]
        if not group_cols:
            continue
        train_mat = df_tr[group_cols].apply(pd.to_numeric, errors="coerce").to_numpy(dtype=np.float32, copy=True)
        active = np.isfinite(train_mat).any(axis=1)
        active_runs_tbl = _state_run_table_12c2(active.astype(np.float32))
        bundle_blocks: List[np.ndarray] = []
        if len(active_runs_tbl):
            for _, rr in active_runs_tbl.iterrows():
                if float(rr.get("state", 0.0)) != 1.0:
                    continue
                s = int(rr.get("start_idx", 0)); e = int(rr.get("end_idx", s))
                block = train_mat[s:e + 1, :].astype(np.float32)
                if np.isfinite(block).any():
                    bundle_blocks.append(block)
        rng_bundle = _rng_for("withings_v9_bundle", entity, "|".join(group_cols), n)
        bundle_y = _withings_v9_bundle_rows_to_length_12c2(bundle_blocks, n, rng_bundle, len(group_cols))
        for j, c in enumerate(group_cols):
            fit = TRAIN_FIT[c]
            rng = _rng_for("withings_v9", entity, c, n)
            col_train_full = pd.to_numeric(df_tr[c], errors="coerce").to_numpy(dtype=np.float32, copy=True)
            col_runs = _withings_v9_extract_runs_12c2(col_train_full)
            vals = fit.train_obs[np.isfinite(fit.train_obs)].astype(np.float32)

            y_run = _withings_v9_sample_runs_to_length_12c2(col_runs, n, rng, vals)
            y_bundle = bundle_y[:, j].astype(np.float32).copy() if bundle_y.size else y_run.copy()
            miss = ~np.isfinite(y_bundle)
            if miss.any():
                y_bundle[miss] = y_run[miss] if y_run.size == y_bundle.size else fit.median
            y_dwell = _withings_v9_temporal_dwell_12c2(fit, n, _rng_for("withings_v9_dwell", entity, c, n), "temporal_dwell")
            y_sparse = _withings_v9_temporal_dwell_12c2(fit, n, _rng_for("withings_v9_sparse", entity, c, n), "sparse_session_plateau")

            for gen, y in [
                ("WithingsSessionRunPreservingV9_train_only", y_run),
                ("WithingsNightBundleSupportFrequencyV9_train_only", y_bundle),
                ("WithingsTemporalDwellCoherenceV9_train_only", y_dwell),
                ("WithingsSparseSessionPlateauV9_train_only", y_sparse),
            ]:
                yy = np.asarray(y, dtype=np.float32).copy()
                if _withings_field_kind_12c2(c) == "count":
                    yy = np.round(np.maximum(yy, 0.0)).astype(np.float32)
                elif _domain_nonnegative(c):
                    yy = np.maximum(yy, 0.0).astype(np.float32)
                if _should_project_to_train_support_12c2(c, fit):
                    yy = _project_to_support(yy, fit.support)
                WITHINGS_JOINT_SESSION_VAL_CACHE[(gen, c)] = _postprocess(c, yy, fit)

