def _synthetic_trainfit_for_v86_cycle_self_test_12c2(col: str, values: List[float]) -> TrainFit:
    x = np.asarray(values, dtype=np.float32)
    obs = x[np.isfinite(x)]
    rounded = np.round(obs.astype(np.float64), 6)
    support64, cnt = np.unique(rounded, return_counts=True)
    support = support64.astype(np.float32)
    support_probs = cnt.astype(np.float64) / max(float(cnt.sum()), 1.0)
    transitions: Dict[float, List[float]] = defaultdict(list)
    prev = None
    run_vals: List[float] = []
    run_lens: List[int] = []
    last = None
    run_len = 0
    for v in x:
        if not np.isfinite(v):
            if last is not None:
                run_vals.append(float(last)); run_lens.append(int(run_len))
            prev = None; last = None; run_len = 0
            continue
        vv = float(np.round(v, 6))
        if prev is not None:
            transitions[float(prev)].append(vv)
        prev = vv
        if last is None or vv != float(last):
            if last is not None:
                run_vals.append(float(last)); run_lens.append(int(run_len))
            last = vv; run_len = 1
        else:
            run_len += 1
    if last is not None:
        run_vals.append(float(last)); run_lens.append(int(run_len))
    trans_vals: Dict[float, np.ndarray] = {}
    trans_probs: Dict[float, np.ndarray] = {}
    for k, vals in transitions.items():
        u, c = np.unique(np.asarray(vals, dtype=np.float64), return_counts=True)
        trans_vals[k] = u.astype(np.float32)
        trans_probs[k] = c.astype(np.float64) / max(float(c.sum()), 1.0)
    qv = float(np.nanmedian(obs)) if obs.size else 0.0
    return TrainFit(
        col=col,
        entity=_infer_entity(col),
        family=_family_for_col(col),
        subfamily=_subfamily_for_col(col),
        field=_field_name(col),
        train_full=x,
        train_obs=obs,
        val_mask=np.ones(int(x.size), dtype=bool),
        obs_n=int(obs.size),
        obs_rate=1.0,
        median=qv,
        mean=float(np.nanmean(obs)) if obs.size else 0.0,
        std=float(np.nanstd(obs)) if obs.size else 0.0,
        q001=qv, q005=qv, q01=qv, q05=qv, q10=qv,
        q50=qv, q90=qv, q95=qv, q99=qv, q995=qv, q999=qv,
        clip_lo=float(np.nanmin(obs)) if obs.size else 0.0,
        clip_hi=float(np.nanmax(obs)) if obs.size else 0.0,
        support=support,
        support_probs=support_probs,
        support_n=int(support.size),
        is_low_card=True,
        is_sparse=False,
        positive_rate=float(np.mean(obs > 0)) if obs.size else 0.0,
        transitions=trans_vals,
        transition_probs=trans_probs,
        run_values=np.asarray(run_vals, dtype=np.float32),
        run_lengths=np.asarray(run_lens, dtype=np.int32),
    )

