def _semantic_generators_for_col(col: str) -> List[str]:
    fit = TRAIN_FIT[col]
    gens: List[str] = []

    def add_if_allowed(g: str) -> None:
        ok, _reason = _generator_semantic_compatible(col, g)
        if ok and g in ALL_GENERATORS and g not in gens:
            gens.append(g)
        elif (not ok) and str(_reason).startswith("semantic_route_veto:"):
            _record_semantic_route_veto_12c2(col, g, "cell12c2_semantic_train_only_router", str(_reason))

    # Neutral TRAIN-only baseline candidate. This is the broadest allowed
    # non-A1 candidate but still requires observed TRAIN values.
    add_if_allowed("ContextContinuousReplay")

    # Strict semantic families.
    if _is_low_card_voltage_candidate_12c2(col):
        add_if_allowed("LowCardVoltageEndpointPlateauV17_entity_endpoint")
        add_if_allowed("LowCardVoltageEndpointPlateauV17_plateau_dwell")
        add_if_allowed("LowCardVoltageEndpointPlateauV17_recent_train_tail")
        add_if_allowed("LowCardVoltageEndpointPlateauV17_transition_safe")
    if _is_low_card_voltage_endpoint_decay_candidate_12c2(col):
        add_if_allowed("LowCardVoltageEndpointDecayV18_publication_safe")
        add_if_allowed("LowCardVoltageEndpointDecayV18_train_support_tail_dwell")
        add_if_allowed("LowCardVoltageEndpointDecayV18_recent_endpoint_frequency")
        add_if_allowed("LowCardVoltageEndpointDecayV18_audit_only_one_step_lower_tail")
    if _is_temperature_environmental_candidate_col_12c2(col, fit):
        add_if_allowed("TemperatureChronologyTODRegimeReplayV1_smooth_quantile_bridge")
        add_if_allowed("TemperatureChronologyTODRegimeReplayV1_val_length_recent_smooth_block")
        add_if_allowed("TemperatureChronologyTODRegimeReplayV1_tod_segment_offset_smooth")
        add_if_allowed("TemperatureChronologyTODRegimeReplayV1_context_residual_gated")
        add_if_allowed("TemperatureSmoothTODSegmentQuantileV2_train_only")
        add_if_allowed("TemperatureSmoothQuantileAR1V2_train_only")
        add_if_allowed("TemperatureSeasonalLevelShiftV2_train_only")
        add_if_allowed("TemperatureContextGatedSmoothV2_train_only")

    if _is_telemetry_like_lowcard_col(col):
        if _is_linkquality(col):
            add_if_allowed("LowCardLinkqualityEndpointTailDwellV18_train_only")
        if _is_link_signal_telemetry_col_12c2(col, fit):
            add_if_allowed("LowCardLinkSignalSupportCompleteFrequencyV19_train_only")
            add_if_allowed(LOWCARD_LINK_SIGNAL_V20_GENERATOR_12C2)
            for _link_v17_gen_12c2 in sorted(LOWCARD_LINK_SIGNAL_V17_GENERATORS_12C2):
                add_if_allowed(_link_v17_gen_12c2)
            for _link_v18_gen_12c2 in sorted(LOWCARD_LINK_SIGNAL_V18_GENERATORS_12C2):
                add_if_allowed(_link_v18_gen_12c2)
        add_if_allowed("LowCardTelemetryRegimeSupportHMMV16_entity_hmm")
        add_if_allowed("LowCardTelemetryRegimeSupportHMMV16_segment_hmm")
        add_if_allowed("LowCardTelemetryRegimeSupportHMMV16_regime_hmm")
        add_if_allowed("LowCardTelemetryRegimeSupportHMMV16_tail_weighted_hmm")
        add_if_allowed("LowCardTelemetryRegimeSupportHMMV16_profile_mixture_hmm")
        add_if_allowed("LowCardTelemetryEndpointDriftDwellV15_terminal_frequency")
        add_if_allowed("LowCardTelemetryEndpointDriftDwellV15_terminal_semimarkov")
        add_if_allowed("LowCardTelemetryEndpointDriftDwellV15_trend_projected_frequency")
        add_if_allowed("LowCardTelemetryEndpointDriftDwellV15_trend_projected_semimarkov")
        add_if_allowed("LowCardTelemetryTrainOnlyProfileDwellV14_frequency_temporal")
        add_if_allowed("LowCardTelemetryTrainOnlyProfileDwellV14_segment_dwell")
        add_if_allowed("LowCardTelemetryTrainOnlyProfileDwellV14_entity_field_profile")
        add_if_allowed("LowCardTelemetryRegimeFrequencyCalibratorV13_entity_regime_frequency")
        add_if_allowed("LowCardTelemetryRegimeFrequencyCalibratorV13_recent_tail_frequency")
        add_if_allowed("LowCardTelemetryRegimeFrequencyCalibratorV13_transition_dwell")
        add_if_allowed("LowCardTelemetryRegimeFrequencyCalibratorV13_mixture_regime_recent")
        add_if_allowed("LowCardTelemetryRegimeFrequencyCalibratorV13_plateau_transition_safe")
        add_if_allowed("LowCardTelemetrySegmentRegimeSupportMixtureV12_segment_frequency")
        add_if_allowed("LowCardTelemetrySegmentRegimeSupportMixtureV12_segment_semimarkov")
        add_if_allowed("LowCardTelemetrySegmentRegimeSupportMixtureV12_entity_field_prior")
        add_if_allowed("LowCardTelemetrySupportMixtureDwellV11_full_recent_mix")
        add_if_allowed("LowCardTelemetrySupportMixtureDwellV11_entity_prior")
        add_if_allowed("LowCardTelemetrySupportMixtureDwellV11_dwell_transition")
        add_if_allowed("LowCardTelemetrySupportFrequencyDwellV10_tail10_frequency")
        add_if_allowed("LowCardTelemetrySupportFrequencyDwellV10_tail10_semimarkov")
        add_if_allowed("LowCardTelemetrySupportFrequencyDwellV10_tail25_frequency")
        add_if_allowed("LowCardTelemetrySupportFrequencyDwellV10_tail25_semimarkov")
        add_if_allowed("LowCardTelemetrySupportFrequencyDwellV10_tail50_frequency")
        add_if_allowed("LowCardTelemetrySupportFrequencyDwellV10_tail50_semimarkov")
        add_if_allowed("LowCardTelemetrySupportFrequencyDwellV10_transition_plateau_safe")
        add_if_allowed("LowCardTelemetrySupportFrequencyDwellV9_publication_entity_frequency")
        add_if_allowed("LowCardTelemetrySupportFrequencyDwellV9_publication_recent_frequency")
        add_if_allowed("LowCardTelemetrySupportFrequencyDwellV9_publication_semimarkov")
        add_if_allowed("LowCardTelemetrySupportFrequencyDwellV9_publication_recent_semimarkov")
        add_if_allowed("LowCardTelemetrySupportFrequencyDwellV8_publication_frequency")
        add_if_allowed("LowCardTelemetrySupportFrequencyDwellV8_publication_semimarkov")
        add_if_allowed("LowCardTelemetrySupportFrequencyDwellV8_publication_ordered_block")
        add_if_allowed("LowCardTelemetrySupportFrequencyDwellV8_publication_plateau_safe")
        add_if_allowed("Markov_SemiMarkov_ordinal_dwell")
        add_if_allowed("LowCardTelemetrySupportFrequencyDwellV8_publication_recent_frequency")
        add_if_allowed("LowCardTelemetrySupportFrequencyDwellV8_publication_recent_semimarkov")

    if _is_ordinal_state_like_col(col) and not _is_telemetry_like_lowcard_col(col):
        add_if_allowed("Markov_SemiMarkov_ordinal_dwell")

    if _is_pressure_candidate_col(col):
        add_if_allowed("PressureQuasiStaticSupportGridDwellV10_train_support")
        add_if_allowed("PressureQuasiStaticSupportGridDwellV10_tail_blend")
        add_if_allowed("PressureQuasiStaticSupportGridDwellV9_publication")
        add_if_allowed("PressureQuasiStaticSupportDwellV8_full_support")
        add_if_allowed("PressureQuasiStaticSupportDwellV8_recent_support")
        add_if_allowed("PressureQuasiStaticSupportDwellV8_plateau_grid")
        add_if_allowed("PressureTelemetryQuantileDwellReplay")
        add_if_allowed("PressureQuasiStaticSupportGridReplayV6_precision_dwell")

    if _is_precip_candidate_col(col):
        add_if_allowed("SparsePrecipitationEventReplay")
        add_if_allowed("SparsePrecipitationDailyAccumulatorV6_event_day_accumulator")

    if _is_true_s5_lifecycle_v13_col_12c2(col, fit=fit):
        add_if_allowed("S5LifecycleSupportCompleteDwellV14_train_only")
        for _s5_v13_gen_12c2 in sorted(S5_V13_GENERATORS_12C2):
            add_if_allowed(_s5_v13_gen_12c2)

    if _is_s5_candidate_col(col):
        if _field_role_12c2(col, fit_override=fit) in {"s5_remaining_life", "s5_lifetime_count", "s5_lifetime_continuous"}:
            add_if_allowed("S5LifecycleSupportCompleteDwellV14_train_only")
        if _s5_field_kind_12c2(col) == "lifetime_count":
            add_if_allowed("S5LifetimeCounterProgressionV4_train_lawful")
            add_if_allowed("S5LifetimeCounterProgressionV3_train_lawful")
        add_if_allowed("S5SemanticEventBoundaryDwellV11_train_only")
        add_if_allowed("S5SemanticSupportDwellV10_train_only")
        if _s5_field_kind_12c2(col) in {"lifetime_count", "lifetime_continuous"}:
            add_if_allowed("S5LifetimeTotalSupportCycleV9_total")
        if _s5_field_kind_12c2(col) == "remaining_life":
            add_if_allowed("S5RemainingLifeTemporalDecayV12_train_only")
            add_if_allowed("S5RemainingLifeDecayResetV9_time_left")
        add_if_allowed("S5SupportStateDwellV8_train_support")
        add_if_allowed("S5SupportStateDwellV8_tail_blend")
        add_if_allowed("S5SupportStateDwellV8_monotone_time_left")
        add_if_allowed("S5LowEventMaintenanceDwellReplayV7_plateau_support")
        add_if_allowed("S5LowEventMaintenanceDwellReplayV7_event_boundary")
        add_if_allowed("S5LowEventMaintenanceDwellReplayV6_low_event_plateau")
        add_if_allowed("S5LowEventMaintenanceDwellReplayV6_event_boundary_coupled")
        add_if_allowed("Markov_SemiMarkov_ordinal_dwell")

    if _is_withings_candidate_col(col):
        if _withings_field_kind_12c2(col) != "count":
            add_if_allowed("WithingsNightSessionBlockDwellV10_train_only")
