        add_if_allowed("WithingsJointSessionCoherenceV7_train_only")
        add_if_allowed("WithingsJointSessionCoherenceV6_train_only")
        if "count" in _norm_txt_12c2(_measurement_field_name_12c2(col)):
            add_if_allowed("WithingsSessionCountSnapshotDwellV6_train_only")
