def _record_semantic_route_veto_12c2(col: str, gen: str, eligible_source: str, reason: str) -> None:
    key = (str(col), str(gen), str(eligible_source), str(reason))
    if key in _SEMANTIC_ROUTE_VETO_KEYS_12C2:
        return
    _SEMANTIC_ROUTE_VETO_KEYS_12C2.add(key)
    SEMANTIC_ROUTE_VETO_AUDIT_ROWS_12C2.append({
        "col": str(col),
        "generator": str(gen),
        "eligible_source": str(eligible_source),
        "semantic_veto_applied": True,
        "semantic_veto_reason": str(reason).replace("semantic_route_veto:", ""),
        "routed_after_veto": False,
        "materialized_after_veto": False,
        "publication_eligible_after_veto": False,
        "no_test_used": True,
    })


