def _cell12c2_synthetic_trainfit_12c2(col: str, values: Sequence[float]) -> TrainFit:
    x = np.asarray(values, dtype=np.float32)
    obs = x[np.isfinite(x)]
    if obs.size == 0:
        obs = np.array([0.0], dtype=np.float32)
    rounded = np.round(obs.astype(np.float64), 6)
    support, counts = np.unique(rounded, return_counts=True)
    support = support.astype(np.float32)
    support_probs = counts.astype(np.float64) / max(float(counts.sum()), 1.0)
    transitions: Dict[float, List[float]] = defaultdict(list)
    run_values: List[float] = []
    run_lengths: List[int] = []
    prev = None
    last = None
    run_len = 0
    for vv_raw in x:
        if not np.isfinite(vv_raw):
            if last is not None:
                run_values.append(float(last))
                run_lengths.append(int(run_len))
            prev = None
            last = None
            run_len = 0
            continue
        vv = float(np.round(float(vv_raw), 6))
        if prev is not None:
            transitions[float(prev)].append(vv)
        prev = vv
        if last is None or vv != float(last):
            if last is not None:
                run_values.append(float(last))
                run_lengths.append(int(run_len))
            last = vv
            run_len = 1
        else:
            run_len += 1
    if last is not None:
        run_values.append(float(last))
        run_lengths.append(int(run_len))
    transition_probs = {
        float(k): (np.ones(len(v), dtype=np.float64) / max(len(v), 1))
        for k, v in transitions.items()
    }
    q = np.quantile(obs.astype(np.float64), [0.001, 0.005, 0.01, 0.05, 0.10, 0.50, 0.90, 0.95, 0.99, 0.995, 0.999])
    return TrainFit(
        col=str(col),
        entity="selftest",
        family="device_telemetry",
        subfamily="selftest",
        field=_measurement_field_name_12c2(col),
        train_full=x,
        train_obs=obs,
        val_mask=np.ones(8, dtype=bool),
        obs_n=int(obs.size),
        obs_rate=1.0,
        median=float(np.nanmedian(obs)),
        mean=float(np.nanmean(obs)),
        std=float(np.nanstd(obs)),
        q001=float(q[0]),
        q005=float(q[1]),
        q01=float(q[2]),
        q05=float(q[3]),
        q10=float(q[4]),
        q50=float(q[5]),
        q90=float(q[6]),
        q95=float(q[7]),
        q99=float(q[8]),
        q995=float(q[9]),
        q999=float(q[10]),
        clip_lo=float(np.nanmin(obs)),
        clip_hi=float(np.nanmax(obs)),
        support=support,
        support_probs=support_probs,
        support_n=int(support.size),
        is_low_card=True,
        is_sparse=False,
        positive_rate=float(np.mean(obs > 0)),
        transitions={float(k): np.asarray(v, dtype=np.float32) for k, v in transitions.items()},
        transition_probs=transition_probs,
        run_values=np.asarray(run_values, dtype=np.float32),
        run_lengths=np.asarray(run_lengths, dtype=np.int32),
    )


