def _with_synthetic_trainfit_selftest_12c2(col: str, values: Sequence[float], fn: Callable[["TrainFit"], bool]) -> bool:
    old_fit = TRAIN_FIT.get(str(col))
    fit = _cell12c2_synthetic_trainfit_12c2(col, values)
    TRAIN_FIT[str(col)] = fit
    try:
        return bool(fn(fit))
    finally:
        if old_fit is None:
            TRAIN_FIT.pop(str(col), None)
        else:
            TRAIN_FIT[str(col)] = old_fit

