def _near_miss_selftest_row_12c2(
    *,
    col: str,
    gen: str,
    role: str,
    auc: float,
    c2st: float,
    ks: float,
    support_jaccard: float = 0.30,
    support_recall: float = 0.30,
    support_precision: float = 0.30,
    frequency_tv: float = 0.30,
    q2_safe: bool = True,
    q2_reason: str = "",
    **extra: Any,
) -> pd.Series:
    base = {
        "col": col,
        "candidate_generator": gen,
        "field_role_12c2": role,
        "materialization_status": "materialized",
        "candidate_valid": True,
        "candidate_selection_eligible": True,
        "candidate_materialized_for_ranking": True,
        "diagnostic_only": False,
        "copy_risk": False,
        "semantic_compatible": True,
        "semantic_compatibility_reason": "selftest_semantic_ok",
        "test_used_for_selection": False,
        "test_used_for_fitting": False,
        "test_materialized_here": False,
        "val_used_for_fitting": False,
        "target_specific_candidate": False,
        "manual_candidate": False,
        "oracle_candidate": False,
        "validity_repair_candidate": False,
        "repair_candidate": False,
        "bridge_candidate": False,
        "role_rescue_candidate": False,
        "target_specific_or_rescue_candidate": False,
        "val_auc_univariate_proxy": float(auc),
        "val_c2st_auc_logreg_1d": float(c2st),
        "val_ks": float(ks),
        "val_wasserstein_norm": 0.75,
        "val_support_jaccard": float(support_jaccard),
        "val_support_recall": float(support_recall),
        "val_support_precision": float(support_precision),
        "val_frequency_tv": float(frequency_tv),
        "support_outside_train_n": 0,
        "q2_temporal_candidate_safe": bool(q2_safe),
        "q2_temporal_risk_reason": str(q2_reason),
        "publication_hard_reason": "publication_contract_not_eligible",
    }
    base.update(extra)
    return pd.Series(base)


def _near_miss_selftest_same_col_12c2(row: pd.Series, baseline_auc: float = 0.70, baseline_c2st: float = 0.70, baseline_ks: float = 0.50) -> pd.DataFrame:
    baseline = row.copy()
