def _inject_s5_v13_explicit_routes_12c2(route_df: pd.DataFrame) -> Tuple[pd.DataFrame, pd.DataFrame]:
    audit_rows: List[Dict[str, Any]] = []
    route_rows: List[Dict[str, Any]] = []
    base_cols = list(route_df.columns) if route_df is not None and len(route_df.columns) else ["col", "generator", "eligible_source"]
    existing_pairs = set()
    if route_df is not None and len(route_df) and {"col", "generator"}.issubset(route_df.columns):
        existing_pairs = set(zip(route_df["col"].astype(str), route_df["generator"].astype(str)))
    for col in CONT_VALUE_COLS:
        c = str(col)
        entity = _infer_entity(c)
        measured_field = _measurement_field_name_12c2(c)
        field_norm = _norm_txt_12c2(measured_field)
        true_s5_lifecycle_col = bool(_is_true_s5_lifecycle_v13_col_12c2(c))
        ps5_guard_triggered = bool(
            "smart_plug_ps5" in c.lower()
            or "ps5_current" in c.lower()
            or "smart_plug_ps5" in str(entity).lower().replace("-", "_")
            or "ps5_current" in str(entity).lower().replace("-", "_")
            or any(tok in field_norm for tok in ["current", "power", "energy", "consumption"])
        )
        added_generators = []
        if true_s5_lifecycle_col and not ps5_guard_triggered:
            for gen in sorted(S5_V13_GENERATORS_12C2):
                if (c, gen) in existing_pairs:
                    continue
                row = {k: np.nan for k in base_cols}
                row["col"] = c
                row["generator"] = gen
                row["eligible_source"] = "cell12c2_s5_v13_explicit_route_injection"
                if "candidate_group" in row:
                    row["candidate_group"] = "specialized_train_only"
                if "generator_group" in row:
                    row["generator_group"] = "specialized_train_only"
                if "generator_family" in row:
                    row["generator_family"] = "s5_lifecycle_v13"
                if "generator_family_diag" in row:
                    row["generator_family_diag"] = "s5_lifecycle_v13"
                if "semantic_compatible" in row:
                    row["semantic_compatible"] = True
                if "route_reason" in row:
                    row["route_reason"] = "true_s5_lifecycle_v13_col"
                route_rows.append(row)
                added_generators.append(gen)
        if true_s5_lifecycle_col and ps5_guard_triggered:
            rejection = "ps5_or_power_guard_triggered"
        elif not true_s5_lifecycle_col:
            rejection = "not_true_s5_lifecycle_v13_col"
        elif not added_generators:
            rejection = "already_routed"
        else:
            rejection = ""
        audit_rows.append({
            "col": c,
            "entity": entity,
            "measured_field": measured_field,
            "true_s5_lifecycle_col": true_s5_lifecycle_col,
            "ps5_guard_triggered": ps5_guard_triggered,
            "route_added_n": int(len(added_generators)),
            "added_generators": "|".join(added_generators),
            "route_rejection_reason": rejection,
            "TEST_values_used": False,
        })
    audit_df = pd.DataFrame(audit_rows)
    if route_rows:
        route_add_df = pd.DataFrame(route_rows)
        for col in route_df.columns:
            if col not in route_add_df.columns:
                route_add_df[col] = np.nan
        for col in route_add_df.columns:
            if col not in route_df.columns:
                route_df[col] = np.nan
        route_df = pd.concat([route_df, route_add_df.loc[:, route_df.columns]], ignore_index=True)
        route_df = route_df.drop_duplicates(["col", "generator"], keep="first")
        route_df = route_df.sort_values(["generator", "col"], kind="mergesort").reset_index(drop=True)
    audit_df.to_csv(s5_v13_explicit_route_injection_audit_csv, index=False)
    return route_df, audit_df


ELIGIBLE_CANDIDATES, CELL12C2_S5_V13_EXPLICIT_ROUTE_INJECTION_AUDIT_DF = _inject_s5_v13_explicit_routes_12c2(ELIGIBLE_CANDIDATES)

