def _df_from_dict(d: Dict[str, np.ndarray]) -> pd.DataFrame:
    if not d:
        return pd.DataFrame(index=df_val.index)
    return pd.DataFrame({k: np.asarray(v, dtype=np.float32) for k, v in d.items()}, index=df_val.index)

