def _cell12c2_bool_count_12c2(
    df: Optional[pd.DataFrame],
    col: str,
    truthy_values: Optional[set] = None,
) -> int:
    if df is None or not isinstance(df, pd.DataFrame) or len(df) == 0:
        return 0
    if truthy_values is None:
        truthy_values = {"true", "1", "yes", "y", "t"}
    if col not in df.columns:
        return 0
    obj = df.loc[:, col]
    if isinstance(obj, pd.DataFrame):
        if obj.shape[1] == 0:
            return 0
        bool_df = obj.apply(
            lambda s: s.astype(str).str.strip().str.lower().isin(truthy_values),
            axis=0,
        ).fillna(False)
        return int(bool_df.any(axis=1).sum())
    s = obj
    if getattr(s, "dtype", None) == bool:
        return int(s.fillna(False).sum())
    return int(s.astype(str).str.strip().str.lower().isin(truthy_values).sum())


def _cell12c2_first_col_12c2(
    df: Optional[pd.DataFrame],
    col: str,
    default: Any = None,
) -> Any:
    if df is None or not isinstance(df, pd.DataFrame) or len(df) == 0 or col not in df.columns:
        return default
    obj = df.loc[:, col]
    if isinstance(obj, pd.DataFrame):
        if obj.shape[1] == 0:
            return default
        return obj.iloc[:, 0]
    return obj


def _temperature_environmental_generator_mask_12c2(df: pd.DataFrame) -> pd.Series:
    if df is None or not isinstance(df, pd.DataFrame) or len(df) == 0:
        return pd.Series(False, index=getattr(df, "index", pd.Index([])))
    if "candidate_generator" not in df.columns:
        return pd.Series(False, index=df.index)
    obj = df.loc[:, "candidate_generator"]
    if isinstance(obj, pd.DataFrame):
        if obj.shape[1] == 0:
            return pd.Series(False, index=df.index)
        obj = obj.iloc[:, 0]
    g = obj.astype(str)
    return (
        g.str.startswith("TemperatureChronologyTODRegimeReplayV1")
        | g.str.startswith("TemperatureSmooth")
        | g.str.startswith("TemperatureSeasonal")
        | g.str.startswith("TemperatureContextGated")
    )


def _dedupe_temperature_environmental_audit_columns_12c2(df: pd.DataFrame) -> Tuple[pd.DataFrame, pd.DataFrame]:
    if df is None or not isinstance(df, pd.DataFrame):
        return pd.DataFrame(), pd.DataFrame(columns=[
            "column_name", "duplicate_count", "kept_first_occurrence", "no_rows_dropped",
        ])
    duplicated = pd.Index(df.columns)[pd.Index(df.columns).duplicated()].unique()
    rows = [
        {
            "column_name": str(c),
            "duplicate_count": int((pd.Index(df.columns) == c).sum()),
            "kept_first_occurrence": True,
            "no_rows_dropped": True,
        }
        for c in duplicated
    ]
    audit = pd.DataFrame(rows, columns=[
        "column_name", "duplicate_count", "kept_first_occurrence", "no_rows_dropped",
    ])
    if len(duplicated):
        return df.loc[:, ~pd.Index(df.columns).duplicated()].copy(), audit
    return df.copy(), audit


