def _ensure_df_12c2(name: str, columns: Sequence[str]) -> pd.DataFrame:
    obj = globals().get(name)
    if isinstance(obj, pd.DataFrame):
        out = obj.copy()
    else:
        out = pd.DataFrame(columns=list(columns))
    for c in columns:
        if c not in out.columns:
            out[c] = np.nan
    return out.loc[:, list(columns)].copy()

def _audit_subset_12c2(mask: pd.Series, cols: List[str]) -> pd.DataFrame:
    if not isinstance(mask, pd.Series):
        mask = pd.Series(False, index=CELL12C2_ALL_VAL_CANDIDATE_METRICS_DF.index)
    mask = mask.reindex(CELL12C2_ALL_VAL_CANDIDATE_METRICS_DF.index, fill_value=False).fillna(False).astype(bool)
    out = CELL12C2_ALL_VAL_CANDIDATE_METRICS_DF.loc[mask].copy()
    for c in cols:
        if c not in out.columns:
            out[c] = np.nan
    return out.loc[:, cols].copy()

def _family_summary_for_audit_12c2(df: pd.DataFrame) -> pd.DataFrame:
    if df is None or len(df) == 0 or "candidate_generator" not in df.columns:
        return pd.DataFrame(columns=_v8_v17_family_summary_cols_12c2)
    tmp = df.copy()
    for _c in ["publication_eligible", "publication_selectable_12c3", "q2_temporal_candidate_safe"]:
        if _c not in tmp.columns:
            tmp[_c] = False
    _metric_aliases_12c2 = {
        "val_auc_univariate_proxy": "auc",
        "val_c2st_auc_logreg_1d": "c2st",
        "val_ks": "ks",
        "val_wasserstein_norm": "wasserstein",
        "val_support_jaccard": "support_jaccard",
        "val_frequency_tv": "frequency_tv",
    }
    for _dst_12c2, _src_12c2 in _metric_aliases_12c2.items():
        if _dst_12c2 not in tmp.columns and _src_12c2 in tmp.columns:
            tmp[_dst_12c2] = tmp[_src_12c2]
    for _c in ["val_auc_univariate_proxy", "val_c2st_auc_logreg_1d", "val_ks", "val_wasserstein_norm", "val_support_jaccard", "val_frequency_tv"]:
        if _c not in tmp.columns:
            tmp[_c] = np.nan
        tmp[_c] = pd.to_numeric(tmp[_c], errors="coerce")
    rows = []
    for gen, grp in tmp.groupby("candidate_generator", dropna=False):
        reasons = (
            grp.get("publication_hard_reason", pd.Series("", index=grp.index))
            .fillna("")
            .astype(str)
            .str.split("|")
            .explode()
        )
        reason_counts = reasons[reasons.astype(str).str.strip().ne("")].value_counts().head(8)
        row = {
            "candidate_generator": str(gen),
            "cols": int(grp.get("col", pd.Series("", index=grp.index)).astype(str).nunique()),
            "candidate_rows": int(len(grp)),
            "publication_eligible_rows": int(grp["publication_eligible"].fillna(False).astype(bool).sum()),
            "publication_selectable_rows": int(grp["publication_selectable_12c3"].fillna(False).astype(bool).sum()),
            "best_val_auc": float(grp["val_auc_univariate_proxy"].min()) if grp["val_auc_univariate_proxy"].notna().any() else np.nan,
            "best_val_c2st": float(grp["val_c2st_auc_logreg_1d"].min()) if grp["val_c2st_auc_logreg_1d"].notna().any() else np.nan,
            "best_val_ks": float(grp["val_ks"].min()) if grp["val_ks"].notna().any() else np.nan,
            "best_val_wasserstein": float(grp["val_wasserstein_norm"].min()) if grp["val_wasserstein_norm"].notna().any() else np.nan,
            "best_support_jaccard": float(grp["val_support_jaccard"].max()) if grp["val_support_jaccard"].notna().any() else np.nan,
            "best_frequency_tv": float(grp["val_frequency_tv"].min()) if grp["val_frequency_tv"].notna().any() else np.nan,
            "q2_safe_rows": int(grp["q2_temporal_candidate_safe"].fillna(False).astype(bool).sum()),
            "top_failure_reasons": "|".join(f"{k}:{int(v)}" for k, v in reason_counts.items()),
            "TEST_values_used": False,
        }
        row["candidate_count"] = row["candidate_rows"]
        row["cols_n"] = row["cols"]
        row["best_val_auc_univariate_proxy"] = row["best_val_auc"]
        row["best_val_c2st_auc_logreg_1d"] = row["best_val_c2st"]
        row["best_val_wasserstein_norm"] = row["best_val_wasserstein"]
        row["best_val_support_jaccard"] = row["best_support_jaccard"]
        row["best_val_frequency_tv"] = row["best_frequency_tv"]
        rows.append(row)
    out = pd.DataFrame(rows)
    for c in _v8_v17_family_summary_cols_12c2:
        if c not in out.columns:
            out[c] = np.nan
    return out.loc[:, _v8_v17_family_summary_cols_12c2].copy()

def _link_signal_v18_candidate_audit_from_metrics_12c2() -> pd.DataFrame:
    _gen_s_12c2 = CELL12C2_ALL_VAL_CANDIDATE_METRICS_DF.get(
        "candidate_generator",
        pd.Series("", index=CELL12C2_ALL_VAL_CANDIDATE_METRICS_DF.index),
    ).fillna("").astype(str)
    src = CELL12C2_ALL_VAL_CANDIDATE_METRICS_DF.loc[_gen_s_12c2.isin(LOWCARD_LINK_SIGNAL_V18_GENERATORS_12C2)].copy()
    out = pd.DataFrame(index=src.index)
    mapping = {
        "col": "col",
        "candidate_generator": "candidate_generator",
        "candidate_id": "candidate_id",
        "support_n_train": "link_signal_v18_support_n_train",
        "support_n_candidate": "link_signal_v18_support_n_candidate",
        "support_recall": "link_signal_v18_support_recall",
        "support_precision": "link_signal_v18_support_precision",
        "support_jaccard": "link_signal_v18_support_jaccard",
        "frequency_tv": "link_signal_v18_frequency_tv",
        "transition_rate_abs_err": "link_signal_v18_transition_rate_abs_err",
        "dwell_similarity": "link_signal_v18_dwell_similarity",
        "plateau_persistence_error": "link_signal_v18_plateau_persistence_error",
        "auc": "val_auc_univariate_proxy",
        "c2st": "val_c2st_auc_logreg_1d",
        "ks": "val_ks",
        "wasserstein": "val_wasserstein_norm",
        "link_signal_v18_candidate_mode": "link_signal_v18_candidate_mode",
        "link_signal_v18_recent_tail_used": "link_signal_v18_recent_tail_used",
        "link_signal_v18_entity_profile_used": "link_signal_v18_entity_profile_used",
        "link_signal_v18_segment_regime_used": "link_signal_v18_segment_regime_used",
        "publication_eligible": "publication_eligible",
        "publication_selectable_12c3": "publication_selectable_12c3",
        "publication_hard_reason": "publication_hard_reason",
        "no_test_values_used": "link_signal_v18_no_test_values_used",
    }
    for dst, src_col in mapping.items():
        out[dst] = src[src_col] if src_col in src.columns else np.nan
    for c in _link_signal_v18_audit_cols_12c2:
        if c not in out.columns:
            out[c] = np.nan
    return out.loc[:, _link_signal_v18_audit_cols_12c2].copy()

def _refresh_v8_v17_audit_frames_12c2() -> None:
    global CELL12C2_LINK_SIGNAL_V17_CANDIDATE_AUDIT_DF
    global CELL12C2_LINK_SIGNAL_V17_FAMILY_SUMMARY_DF
    global CELL12C2_LINK_SIGNAL_V18_CANDIDATE_AUDIT_DF
