def _family_summary_for_audit_12c2(df: pd.DataFrame) -> pd.DataFrame:
    if df is None or len(df) == 0 or "candidate_generator" not in df.columns:
        return pd.DataFrame(columns=_v8_v17_family_summary_cols_12c2)
    tmp = df.copy()
    for _c in ["publication_eligible", "publication_selectable_12c3", "q2_temporal_candidate_safe"]:
        if _c not in tmp.columns:
            tmp[_c] = False
    _metric_aliases_12c2 = {
        "val_auc_univariate_proxy": "auc",
        "val_c2st_auc_logreg_1d": "c2st",
        "val_ks": "ks",
        "val_wasserstein_norm": "wasserstein",
        "val_support_jaccard": "support_jaccard",
        "val_frequency_tv": "frequency_tv",
    }
    for _dst_12c2, _src_12c2 in _metric_aliases_12c2.items():
        if _dst_12c2 not in tmp.columns and _src_12c2 in tmp.columns:
            tmp[_dst_12c2] = tmp[_src_12c2]
    for _c in ["val_auc_univariate_proxy", "val_c2st_auc_logreg_1d", "val_ks", "val_wasserstein_norm", "val_support_jaccard", "val_frequency_tv"]:
        if _c not in tmp.columns:
            tmp[_c] = np.nan
        tmp[_c] = pd.to_numeric(tmp[_c], errors="coerce")
    rows = []
    for gen, grp in tmp.groupby("candidate_generator", dropna=False):
        reasons = (
            grp.get("publication_hard_reason", pd.Series("", index=grp.index))
            .fillna("")
            .astype(str)
            .str.split("|")
            .explode()
        )
        reason_counts = reasons[reasons.astype(str).str.strip().ne("")].value_counts().head(8)
        row = {
            "candidate_generator": str(gen),
            "candidate_rows": int(len(grp)),
            "cols": int(grp.get("col", pd.Series("", index=grp.index)).astype(str).nunique()),
            "publication_eligible_rows": int(grp["publication_eligible"].fillna(False).astype(bool).sum()),
            "publication_selectable_rows": int(grp["publication_selectable_12c3"].fillna(False).astype(bool).sum()),
            "best_val_auc": float(grp["val_auc_univariate_proxy"].min()) if grp["val_auc_univariate_proxy"].notna().any() else np.nan,
            "best_val_c2st": float(grp["val_c2st_auc_logreg_1d"].min()) if grp["val_c2st_auc_logreg_1d"].notna().any() else np.nan,
            "best_val_ks": float(grp["val_ks"].min()) if grp["val_ks"].notna().any() else np.nan,
            "best_val_wasserstein": float(grp["val_wasserstein_norm"].min()) if grp["val_wasserstein_norm"].notna().any() else np.nan,
            "best_support_jaccard": float(grp["val_support_jaccard"].max()) if grp["val_support_jaccard"].notna().any() else np.nan,
            "best_frequency_tv": float(grp["val_frequency_tv"].min()) if grp["val_frequency_tv"].notna().any() else np.nan,
            "q2_safe_rows": int(grp["q2_temporal_candidate_safe"].fillna(False).astype(bool).sum()),
            "top_failure_reasons": "|".join(f"{k}:{int(v)}" for k, v in reason_counts.items()),
            "TEST_values_used": False,
        }
        row["candidate_count"] = row["candidate_rows"]
        row["cols_n"] = row["cols"]
        row["best_val_auc_univariate_proxy"] = row["best_val_auc"]
        row["best_val_c2st_auc_logreg_1d"] = row["best_val_c2st"]
        row["best_val_wasserstein_norm"] = row["best_val_wasserstein"]
        row["best_val_support_jaccard"] = row["best_support_jaccard"]
        row["best_val_frequency_tv"] = row["best_frequency_tv"]
        rows.append(row)
    out = pd.DataFrame(rows)
    for c in _v8_v17_family_summary_cols_12c2:
        if c not in out.columns:
            out[c] = np.nan
    return out.loc[:, _v8_v17_family_summary_cols_12c2].copy()

