def _counter_v3_publication_contract_self_test_12c2(
    test_name: str,
    train_values: List[float],
    cand_values: List[float],
    expected_flag: str,
) -> Dict[str, Any]:
    col = "iot__door_window_sensor_pid_005__sensor__trigger_count__value"
    old_fit = TRAIN_FIT.get(col)
    fit = _synthetic_trainfit_for_v86_cycle_self_test_12c2(col, train_values)
    TRAIN_FIT[col] = fit
    try:
        metrics = _counter_progression_eval_12c2(
            np.asarray(cand_values, dtype=np.float32),
            np.asarray(cand_values, dtype=np.float32),
            fit.train_full,
            col,
        )
        row = {
            "candidate_id": f"selftest_{test_name}",
            "col": col,
            "source_col": col,
            "candidate_generator": "CounterAccumulatorProgressionV3_train_lawful",
            "generator": "CounterAccumulatorProgressionV3_train_lawful",
            "requested_generator": "CounterAccumulatorProgressionV3_train_lawful",
            "actual_generator": "CounterAccumulatorProgressionV3_train_lawful",
            "materialization_status": "materialized",
            "semantic_compatible": True,
            "train_observed_n": max(int(MIN_TRAIN_OBS), int(fit.obs_n)),
            "val_observed_n": int(max(1, len(cand_values))),
            "publication_hard_reason": "",
            "copy_risk": False,
            "validity_repair_candidate": False,
            "target_specific_candidate": False,
            "role_rescue_candidate": False,
            "target_specific_or_rescue_candidate": False,
            "split_shift_quarantine_v1": False,
            "upstream13_train_compatible_generator_failure_v1": False,
            "test_used_for_selection": False,
            "test_materialized_here": False,
            "test_used_for_fitting": False,
            "val_used_for_fitting": False,
        }
        row.update(metrics)
        finalized = _finalize_candidate_publication_contract_12c2(pd.DataFrame([row])).iloc[0].to_dict()
        return {
            "test_name": test_name,
            "status": "checked",
            "passed": bool(metrics.get(expected_flag, False) and not bool(finalized.get("publication_eligible", True))),
            "reason": str(metrics.get("counter_v3_progression_failure_reason", "")),
            "no_test_used": True,
        }
    finally:
        if old_fit is None:
            TRAIN_FIT.pop(col, None)
        else:
            TRAIN_FIT[col] = old_fit

