def _lowcard_v13_train_val_support_row_12c2(col: str) -> Dict[str, Any]:
    fit = TRAIN_FIT[col]
    val_x = _ensure_numeric_series(df_val, col, N_VAL).to_numpy(dtype=np.float32, copy=False)
    tr = _finite_np(fit.train_obs)
    va = _finite_np(val_x[fit.val_mask])
    if tr.size == 0 or va.size == 0:
        return {
            "train_val_support_jaccard": np.nan,
            "val_only_support_n": np.nan,
            "val_range_outside_train": np.nan,
        }
    tr_s = set(np.round(tr.astype(np.float64), 6).tolist())
    va_s = set(np.round(va.astype(np.float64), 6).tolist())
    union = tr_s | va_s
    return {
        "train_val_support_jaccard": float(len(tr_s & va_s) / max(len(union), 1)),
        "val_only_support_n": int(len(va_s - tr_s)),
        "val_range_outside_train": bool(float(np.min(va)) < float(np.min(tr)) - 1e-8 or float(np.max(va)) > float(np.max(tr)) + 1e-8),
    }

