def _candidate_family_audit_12c2(prefix_or_name: str, cols: List[str]) -> pd.DataFrame:
    if prefix_or_name.endswith("*"):
        mask = CELL12C2_ALL_VAL_CANDIDATE_METRICS_DF["candidate_generator"].astype(str).str.startswith(prefix_or_name[:-1])
    else:
        mask = CELL12C2_ALL_VAL_CANDIDATE_METRICS_DF["candidate_generator"].astype(str).eq(prefix_or_name)
    df = CELL12C2_ALL_VAL_CANDIDATE_METRICS_DF.loc[mask].copy()
    for c in cols:
        if c not in df.columns:
            df[c] = np.nan
    return df.loc[:, cols].copy() if len(df) else pd.DataFrame(columns=cols)


