# TRAIN→VAL support/range drift audit.
# This is explanatory only. It does not change candidate validity or publication eligibility.
support_shift_rows = []
for c in CONT_VALUE_COLS:
    fit = TRAIN_FIT[c]
    val_x = _ensure_numeric_series(df_val, c, N_VAL).to_numpy(dtype=np.float32, copy=False)
    tr = _finite_np(fit.train_obs)
    va = _finite_np(val_x)

    if tr.size == 0 or va.size == 0:
        support_shift_rows.append({
            "col": c,
            "family": fit.family,
            "synthesis_subfamily": fit.subfamily,
            "train_support_n": int(fit.support_n),
            "val_support_n": 0,
            "train_val_support_jaccard": np.nan,
            "val_only_support_n": np.nan,
            "val_only_support_frac": np.nan,
            "train_only_support_n": np.nan,
            "train_val_frequency_tv": np.nan,
            "train_val_ks": np.nan,
            "train_val_auc_proxy": np.nan,
            "val_range_inside_train_range": False,
            "val_range_outside_train": False,
            "train_val_split_shift_likely": False,
        })
        continue

    tr_s = set(np.unique(np.round(tr, 6)).tolist())
    va_s = set(np.unique(np.round(va, 6)).tolist())
    inter = tr_s & va_s
    union = tr_s | va_s

    tr_min, tr_max = float(np.min(tr)), float(np.max(tr))
    va_min, va_max = float(np.min(va)), float(np.max(va))
    val_range_outside = bool(va_min < tr_min - 1e-8 or va_max > tr_max + 1e-8)
    val_range_inside_train_range = bool(not val_range_outside)
    sj = float(len(inter) / max(len(union), 1))
    val_only_support_frac = float(len(va_s - tr_s) / max(len(va_s), 1))
    tr_counts = Counter(np.round(tr.astype(np.float64), 6).tolist())
    va_counts = Counter(np.round(va.astype(np.float64), 6).tolist())
    tr_n = max(float(len(tr)), 1.0)
    va_n = max(float(len(va)), 1.0)
    train_val_frequency_tv = float(
        0.5 * sum(abs(tr_counts.get(u, 0) / tr_n - va_counts.get(u, 0) / va_n) for u in union)
    )
    train_val_ks = _ks(tr, va, f"{c}::train_val_support_shift")
    train_val_auc_proxy = _auc_proxy(tr, va, f"{c}::train_val_support_shift")

    split_shift_likely = bool(
        (_is_linkquality(c) or _is_voltage_battery_temp(c) or _is_s5(c) or _is_counter_like(c))
        and (
            sj < 0.25
            or len(va_s - tr_s) > 0
            or val_range_outside
        )
    )

    support_shift_rows.append({
        "col": c,
        "family": fit.family,
        "synthesis_subfamily": fit.subfamily,
        "train_support_n": int(len(tr_s)),
        "val_support_n": int(len(va_s)),
        "train_val_support_jaccard": sj,
        "val_only_support_n": int(len(va_s - tr_s)),
        "val_only_support_frac": val_only_support_frac,
        "train_only_support_n": int(len(tr_s - va_s)),
        "train_val_frequency_tv": train_val_frequency_tv,
        "train_val_ks": train_val_ks,
        "train_val_auc_proxy": train_val_auc_proxy,
        "train_min": tr_min,
        "train_max": tr_max,
        "val_min": va_min,
        "val_max": va_max,
        "val_range_inside_train_range": val_range_inside_train_range,
        "val_range_outside_train": val_range_outside,
        "train_val_split_shift_likely": split_shift_likely,
    })

