def _explode_reason_counts_12c2(df: pd.DataFrame, group_cols: list[str]) -> pd.DataFrame:
    rows = []
    if df is None or len(df) == 0:
        return pd.DataFrame(columns=group_cols + ["reason", "rows", "cols"])

    for _, r in df.iterrows():
        reason_blob = str(r.get("publication_hard_reason", "") or r.get("publication_ineligible_reason", ""))
        toks = [t.strip() for t in reason_blob.split("|") if t.strip()]
        if not toks:
            toks = ["publication_eligible_or_no_reason"]
        for t in toks:
            row = {g: r.get(g, "") for g in group_cols}
            row.update({
                "reason": t,
                "col": str(r.get("col", "")),
            })
            rows.append(row)

    long = pd.DataFrame(rows)
    if not len(long):
        return pd.DataFrame(columns=group_cols + ["reason", "rows", "cols"])

    return (
        long.groupby(group_cols + ["reason"], dropna=False)
        .agg(rows=("reason", "size"), cols=("col", "nunique"))
        .reset_index()
        .sort_values(["rows", "cols"], ascending=[False, False])
    )


