def _dominant_reason_12c2(s: pd.Series) -> str:
    vals = []
    for x in s.fillna("").astype(str).tolist():
        vals.extend([p for p in x.split("|") if p])
    if not vals:
        return ""
    return Counter(vals).most_common(1)[0][0]


def _unserved_recommendation_12c2(
    train_observed_n: int,
    candidates_routed_n: int,
    publication_eligible_n: int,
    candidate_selection_eligible_n: int,
    train_val_support_jaccard: float,
    val_range_outside_train: bool,
    dominant_reason: str,
    best_auc: float,
    best_c2st: float,
    best_ks: float,
) -> str:
    if train_observed_n <= 0:
        return "no_train_observations"
    if bool(val_range_outside_train) or (np.isfinite(train_val_support_jaccard) and train_val_support_jaccard < 0.15):
        return "irreducible_train_val_support_shift_or_range_shift"
    if candidates_routed_n <= 0:
        return "candidate_generation_missing_for_semantic_family"
    if publication_eligible_n > 0:
        return "publication_candidate_available_for_12c3"
    if "counter_progression_invalid_publication_gate" in str(dominant_reason):
        return "counter_progression_invalid"
    if candidate_selection_eligible_n > 0 and (
        (np.isfinite(best_auc) and best_auc >= 0.70)
        or (np.isfinite(best_c2st) and best_c2st >= UNIVERSAL_C2ST_PUBLICATION_WARN)
        or (np.isfinite(best_ks) and best_ks >= 0.35)
    ):
        return "candidate_metrics_too_separable"
    return "rankable_only_no_publication_safe_candidate"


_unserved_rows_12c2: List[Dict[str, Any]] = []
for _col in CONT_VALUE_COLS:
    _fit = TRAIN_FIT[_col]
    _sub = CELL12C2_ALL_VAL_CANDIDATE_METRICS_DF.loc[
        CELL12C2_ALL_VAL_CANDIDATE_METRICS_DF["col"].astype(str).eq(str(_col))
    ].copy()
    _val_vals = _finite_np(_ensure_numeric_series(df_val, _col, N_VAL).to_numpy(dtype=np.float32, copy=False))
    _tr_support = set(_round_support(_fit.train_obs).tolist())
    _val_support = set(_round_support(_val_vals).tolist())
    _tv_inter = _tr_support & _val_support
    _tv_union = _tr_support | _val_support
    _train_val_support_jaccard = float(len(_tv_inter) / max(len(_tv_union), 1)) if _tv_union else float("nan")
    _val_only_support_n = int(len(_val_support - _tr_support))
    _val_range_outside_train = bool(
        _val_vals.size > 0
        and _fit.obs_n > 0
        and (
            float(np.nanmin(_val_vals)) < float(np.nanmin(_fit.train_obs)) - 1e-9
            or float(np.nanmax(_val_vals)) > float(np.nanmax(_fit.train_obs)) + 1e-9
        )
    )
    _rankable = _sub.loc[_sub.get("candidate_selection_eligible", pd.Series(False, index=_sub.index)).fillna(False).astype(bool)].copy()
    if len(_rankable):
        _rankable["_rank_score"] = (
            _rankable.get("val_auc_univariate_proxy", pd.Series(np.nan, index=_rankable.index)).fillna(9.0).astype(float)
            + _rankable.get("val_ks", pd.Series(np.nan, index=_rankable.index)).fillna(9.0).astype(float)
            + _rankable.get("val_wasserstein_norm", pd.Series(np.nan, index=_rankable.index)).fillna(9.0).astype(float)
        )
        _best_rank = _rankable.sort_values("_rank_score", ascending=True).iloc[0].to_dict()
    else:
        _best_rank = {}
    _pub = _sub.loc[_sub.get("publication_eligible", pd.Series(False, index=_sub.index)).fillna(False).astype(bool)].copy()
    if len(_pub):
        _pub["_rank_score"] = (
            _pub.get("val_auc_univariate_proxy", pd.Series(np.nan, index=_pub.index)).fillna(9.0).astype(float)
            + _pub.get("val_ks", pd.Series(np.nan, index=_pub.index)).fillna(9.0).astype(float)
            + _pub.get("val_wasserstein_norm", pd.Series(np.nan, index=_pub.index)).fillna(9.0).astype(float)
        )
        _best_pub = _pub.sort_values("_rank_score", ascending=True).iloc[0].to_dict()
    else:
        _best_pub = {}
    _dominant = _dominant_reason_12c2(_sub.get("publication_hard_reason", pd.Series("", index=_sub.index)))
    _best_auc = float(_best_rank.get("val_auc_univariate_proxy", np.nan))
    _best_c2st = float(_best_rank.get("val_c2st_auc_logreg_1d", np.nan))
    _best_ks = float(_best_rank.get("val_ks", np.nan))
    _unserved_rows_12c2.append({
        "col": _col,
        "entity": _fit.entity,
        "family": _fit.family,
        "synthesis_subfamily": _fit.subfamily,
        "parsed_measurement_field": _measurement_field_name_12c2(_col),
        "train_observed_n": int(_fit.obs_n),
        "train_support_n": int(_fit.support_n),
        "train_val_support_jaccard": _train_val_support_jaccard,
        "val_only_support_n": _val_only_support_n,
        "val_range_outside_train": bool(_val_range_outside_train),
        "candidates_routed_n": int(len(_sub)),
        "candidate_selection_eligible_n": int(_sub.get("candidate_selection_eligible", pd.Series(False, index=_sub.index)).fillna(False).astype(bool).sum()),
        "publication_eligible_n": int(_sub.get("publication_eligible", pd.Series(False, index=_sub.index)).fillna(False).astype(bool).sum()),
        "publication_selectable_12c3_n": int(_sub.get("publication_selectable_12c3", pd.Series(False, index=_sub.index)).fillna(False).astype(bool).sum()),
        "best_rankable_candidate_id": str(_best_rank.get("candidate_id", "")),
        "best_rankable_generator": str(_best_rank.get("candidate_generator", "")),
        "best_rankable_auc": _best_auc,
        "best_rankable_c2st": _best_c2st,
        "best_rankable_ks": _best_ks,
        "best_rankable_wasserstein_norm": float(_best_rank.get("val_wasserstein_norm", np.nan)),
        "best_rankable_support_jaccard": float(_best_rank.get("val_support_jaccard", np.nan)),
        "best_publication_candidate_id": str(_best_pub.get("candidate_id", "")),
        "best_publication_generator": str(_best_pub.get("candidate_generator", "")),
        "dominant_publication_ineligible_reason": _dominant,
        "recommended_next_action": _unserved_recommendation_12c2(
            int(_fit.obs_n),
            int(len(_sub)),
            int(_sub.get("publication_eligible", pd.Series(False, index=_sub.index)).fillna(False).astype(bool).sum()),
            int(_sub.get("candidate_selection_eligible", pd.Series(False, index=_sub.index)).fillna(False).astype(bool).sum()),
            _train_val_support_jaccard,
            _val_range_outside_train,
            _dominant,
            _best_auc,
            _best_c2st,
            _best_ks,
        ),
    })

CELL12C2_UNSERVED_COLUMN_DIAGNOSTIC_DF = pd.DataFrame(_unserved_rows_12c2)

def _num_12c2(df: pd.DataFrame, col: str, default: float = np.nan) -> pd.Series:
    if col in df.columns:
        return pd.to_numeric(df[col], errors="coerce").reindex(df.index)
    return pd.Series(default, index=df.index, dtype="float64")


def _bool_12c2(df: pd.DataFrame, col: str, default: bool = False) -> pd.Series:
    if col not in df.columns:
        return pd.Series(bool(default), index=df.index, dtype="bool")

    s = df[col].reindex(df.index)

    if pd.api.types.is_bool_dtype(s.dtype):
        return s.fillna(bool(default)).astype(bool)

    if pd.api.types.is_numeric_dtype(s.dtype):
        fill_value = 1.0 if bool(default) else 0.0
        return (
            pd.to_numeric(s, errors="coerce")
            .fillna(fill_value)
            .astype(float)
            .ne(0.0)
            .astype(bool)
        )

    def _one_12c2(x: Any) -> bool:
        try:
            if pd.isna(x):
                return bool(default)
        except Exception:
            pass
        if isinstance(x, (bool, np.bool_)):
            return bool(x)
        if isinstance(x, (int, float, np.integer, np.floating)):
            try:
                if not np.isfinite(float(x)):
                    return bool(default)
                return bool(float(x) != 0.0)
            except Exception:
                return bool(default)
        ss = str(x).strip().lower()
        if ss in {"true", "1", "1.0", "yes", "y", "t"}:
            return True
        if ss in {"false", "0", "0.0", "no", "n", "f", "", "nan", "none", "null", "<na>"}:
            return False
        return bool(default)

    return s.map(_one_12c2).astype(bool)


def _str_12c2(df: pd.DataFrame, col: str, default: str = "") -> pd.Series:
    if col in df.columns:
        s = df[col].reindex(df.index)
        return s.astype("object").where(~s.isna(), str(default)).astype(str)
    return pd.Series(str(default), index=df.index, dtype="object")


def _truthy_scalar_12c2(x: Any, default: bool = False) -> bool:
    if x is None:
        return bool(default)
    if isinstance(x, (bool, np.bool_)):
        return bool(x)
    try:
        if pd.isna(x):
            return bool(default)
    except Exception:
        pass
    if isinstance(x, str):
        return x.strip().lower() in {"true", "1", "yes", "y", "t"}
    return bool(x)


def _publication_failure_bucket_12c2(row: dict) -> str:
    if _truthy_scalar_12c2(row.get("publication_eligible", False), False):
        return "publication_eligible"
    reason = " ".join([
        str(row.get("publication_hard_reason", "")),
        str(row.get("publication_ineligible_reason", "")),
        str(row.get("non_a1_publication_risk_reason", "")),
        str(row.get("semantic_compatibility_reason", "")),
    ]).lower()
    materialized = str(row.get("materialization_status", "")).lower() == "materialized"
    val_obs = pd.to_numeric(pd.Series([row.get("val_observed_n", np.nan)]), errors="coerce").iloc[0]
    if (not materialized) or (pd.notna(val_obs) and float(val_obs) <= 0):
        return "not_materialized_or_no_val_overlap"
    if (
        not _truthy_scalar_12c2(row.get("semantic_compatible", True), True)
        or "semantic_incompatible" in reason
        or "semantic_route_veto" in reason
    ):
        return "semantic_or_route_failure"
    if "counter_progression_invalid_publication_gate" in reason:
        return "counter_progression_failure"
    if any(x in reason for x in [
        "low_card_support_precision_lt_min",
        "low_card_support_recall_lt_min",
        "low_card_support_jaccard_lt_min",
    ]):
        return "support_precision_recall_jaccard_failure"
    if "low_card_frequency_tv_gt_max" in reason:
        return "frequency_tv_failure"
    if any(x in reason for x in [
        "auc_ks",
        "c2st_ks",
        "universal_auc",
        "universal_c2st",
        "dense_auc",
        "dense_c2st",
        "withings_summary_auc",
        "withings_summary_c2st",
        "s5_lifetime_auc",
        "s5_lifetime_c2st",
        "cumulative_power_auc",
        "cumulative_power_c2st",
    ]):
        return "auc_ks_or_c2st_ks_failure"
    if "wass" in reason:
        return "wasserstein_joint_failure"
    if (
        ("copy_risk" in reason)
        or _truthy_scalar_12c2(row.get("copy_risk", False), False)
        or _truthy_scalar_12c2(row.get("diagnostic_only", False), False)
    ):
        return "copy_risk_or_diagnostic_only"
    train_val_j = pd.to_numeric(pd.Series([row.get("train_val_support_jaccard", np.nan)]), errors="coerce").iloc[0]
    if (pd.notna(train_val_j) and float(train_val_j) < 0.25) or _truthy_scalar_12c2(row.get("val_range_outside_train", False), False):
        return "train_val_support_shift_likely"
    return "publication_risky_other"


def _candidate_rescue_score_12c2(df: pd.DataFrame) -> pd.Series:
    auc = _num_12c2(df, "val_auc_univariate_proxy", 9.0).fillna(9.0)
    c2st = _num_12c2(df, "val_c2st_auc_logreg_1d", 9.0).fillna(9.0)
    ks = _num_12c2(df, "val_ks", 9.0).fillna(9.0)
    wass = _num_12c2(df, "val_wasserstein_norm", 9.0).fillna(9.0)
    support_j = _num_12c2(df, "val_support_jaccard", 0.0).fillna(0.0)
    support_recall = _num_12c2(df, "val_support_recall", 0.0).fillna(0.0)
    support_precision = _num_12c2(df, "val_support_precision", 0.0).fillna(0.0)
    freq_tv = _num_12c2(df, "val_frequency_tv", 1.0).fillna(1.0)
    score = (
        auc
        + c2st
        + ks
        + 0.20 * wass
        + 0.75 * freq_tv
        - 0.50 * support_j
        - 0.25 * support_recall
        - 0.25 * support_precision
    )
    score = score + np.where(~_bool_12c2(df, "candidate_selection_eligible", False), 100.0, 0.0)
    score = score + np.where(~_bool_12c2(df, "candidate_materialized_for_ranking", False), 100.0, 0.0)
    score = score + np.where(~_bool_12c2(df, "semantic_compatible", True), 100.0, 0.0)
    test_flag = (
        _bool_12c2(df, "test_used_for_fitting", False)
        | _bool_12c2(df, "test_used_for_selection", False)
        | _bool_12c2(df, "test_materialized_here", False)
    )
    score = score + np.where(test_flag, 100.0, 0.0)
    score = score + np.where(_bool_12c2(df, "copy_risk", False), 10.0, 0.0)
    score = score + np.where(_bool_12c2(df, "diagnostic_only", False), 5.0, 0.0)
    support_hard = _bool_12c2(df, "support_hard_publication_col", False)
    score = score + np.where(
        support_hard,
        (1.0 - support_j) + 0.5 * (1.0 - support_recall) + 0.5 * (1.0 - support_precision) + freq_tv,
        0.0,
    )
    counter_guard = _str_12c2(df, "field_role_12c2", "").isin(["event_counter_integer", "cumulative_power_continuous"])
    score = score + np.where(counter_guard & ~_bool_12c2(df, "val_counter_progression_safe", True), 20.0, 0.0)
    return pd.Series(score, index=df.index, dtype="float64")


_rescue_bool_nullable_selftest_12c2 = pd.DataFrame({
    "val_counter_progression_safe": pd.Series([True, False, pd.NA], dtype="boolean"),
    "field_role_12c2": ["event_counter_integer", "event_counter_integer", "dense_environmental"],
})
_rescue_bool_default_true_12c2 = _bool_12c2(
    _rescue_bool_nullable_selftest_12c2,
    "val_counter_progression_safe",
    True,
).tolist()
_rescue_bool_default_false_12c2 = _bool_12c2(
    _rescue_bool_nullable_selftest_12c2,
    "val_counter_progression_safe",
    False,
).tolist()
_rescue_bool_score_selftest_12c2 = _candidate_rescue_score_12c2(_rescue_bool_nullable_selftest_12c2)
if (
    _rescue_bool_default_true_12c2 != [True, False, True]
    or _rescue_bool_default_false_12c2 != [True, False, False]
    or len(_rescue_bool_score_selftest_12c2) != len(_rescue_bool_nullable_selftest_12c2)
):
    raise RuntimeError(
        "[Cell12.c.2] Nullable BooleanDtype rescue scoring self-test failed. "
        f"default_true={_rescue_bool_default_true_12c2} | "
        f"default_false={_rescue_bool_default_false_12c2}"
    )


def _recommended_upstream_fix_family_12c2(col: str, family: str, synthesis_subfamily: str, field_role: str) -> str:
    role = str(field_role)
    fam = str(family)
    sub = str(synthesis_subfamily).lower()
    field = _measurement_field_name_12c2(str(col)).lower()
    if role == "telemetry_discrete":
        return "low_card_telemetry_distribution_dwell_family"
    if role in {"s5_remaining_life", "s5_lifetime_count", "s5_lifetime_continuous", "s5_session_measure", "s5_discrete_state"}:
        return "s5_semantic_progression_family"
    if role in {"cumulative_power_continuous", "event_counter_integer"} or fam == "cumulative_count":
        return "counter_cumulative_progression_family"
    if role.startswith("withings"):
        return "withings_session_coherence_family"
    if role == "motion_axis":
        return "motion_axis_support_dwell_family"
    if fam == "pressure":
        return "pressure_quasistatic_support_family"
    if ("precipitation" in sub) or ("rain" in field) or ("precip" in field):
        return "sparse_precipitation_family"
    return "inspect_general_context_or_dense_family"


def _as_bool_12c2(x: Any, default: bool = False) -> bool:
    if x is None:
        return bool(default)
    if isinstance(x, (bool, np.bool_)):
        return bool(x)
    try:
        if pd.isna(x):
            return bool(default)
    except Exception:
        pass

    # Numeric 0/1, 0.0/1.0
    try:
        num = pd.to_numeric(pd.Series([x]), errors="coerce").iloc[0]
        if pd.notna(num):
            return bool(float(num) != 0.0)
    except Exception:
        pass

    if isinstance(x, str):
        return x.strip().lower() in {"true", "1", "1.0", "yes", "y", "t"}

    return bool(x)


def _as_float_12c2(x: Any, default: float = np.nan) -> float:
    try:
        v = pd.to_numeric(pd.Series([x]), errors="coerce").iloc[0]
        return float(v) if pd.notna(v) else float(default)
    except Exception:
        return float(default)


def _rescue_diagnostic_class_12c2(row: dict) -> str:
    if int(row.get("publication_eligible_rows_n", 0)) > 0:
        return "publication_candidate_available"
    if int(row.get("rankable_rows_n", 0)) == 0:
        return "route_gap_or_no_rankable_candidate"
    bucket = str(row.get("dominant_failure_bucket", ""))
    support_shift = (
        (pd.notna(row.get("train_val_support_jaccard", np.nan)) and float(row.get("train_val_support_jaccard", np.nan)) < 0.25)
        or bool(row.get("val_range_outside_train", False))
    )
    if support_shift and bucket in {
        "support_precision_recall_jaccard_failure",
        "frequency_tv_failure",
        "wasserstein_joint_failure",
        "train_val_support_shift_likely",
    }:
        return "likely_irreducible_train_val_support_shift"
    if bucket in {"support_precision_recall_jaccard_failure", "frequency_tv_failure"}:
        return "support_frequency_gate_failure"
    if bucket == "auc_ks_or_c2st_ks_failure":
        return "separability_gate_failure"
    if bucket == "counter_progression_failure":
        return "counter_progression_gate_failure"
    if bucket in {"not_materialized_or_no_val_overlap", "semantic_or_route_failure"}:
        return "materialization_or_semantic_failure"
    return "rankable_but_publication_risky_other"


